window.BOOK={"units":[{"n":1,"title":"وطننا العربي (خصائص وتحديات)","extra":{"title":"تقييم الوحدة الأولى","pages":[37,39]}},{"n":2,"title":"الدولة الإسلامية من النشأة إلى العالمية","extra":{"title":"تقييم الوحدة الثانية","pages":[71,73]}},{"n":3,"title":"وطننا العربي والتنمية الاقتصادية","extra":{"title":"تقييم الوحدة الثالثة","pages":[106,107]}}],"review":{"title":"مراجعة عامة على الفصل الدراسي الأول","pages":[108,111]},"lessons":[{"id":"u1l1","unit":1,"n":1,"title":"وطننا العربي (الموقع - الأهمية)","bookPages":[8,15],"icon":"globe","objectives":["أحدّد الموقع الفلكي والجغرافي للوطن العربي.","أفسّر أهمية موقع الوطن العربي (الحضارية – الاقتصادية – الدينية – الإستراتيجية).","أميّز بين دول الجناح العربي الإفريقي والجناح العربي الآسيوي.","أعبّر عن اعتزازي بانتمائي العربي بأساليب متنوعة."],"panels":[{"title":"وطن واحد يجمعنا","src":[8],"blocks":[{"t":"intro","text":"لكل إنسان وطن ينتمي إليه ويعيش فيه، ووطننا العربي يجمعه لغة وعادات وتقاليد واحدة وتاريخ مشترك."},{"t":"stats","items":[{"v":"٢٢","l":"دولة عربية","d":"يضم وطننا العربي ٢٢ دولة."},{"v":"٢","l":"قارتان","d":"تقع هذه الدول في قارتين هما إفريقيا وآسيا."},{"v":"١٣","u":"مليون كم²","l":"المساحة تقريبًا","d":"تبلغ مساحة وطننا العربي حوالي ١٣ مليون كيلومتر مربع."}]},{"t":"fact","kind":"حقائق تاريخية","text":"تحرص مصر منذ القِدَم على إقامة علاقات طيبة مع الدول العربية، قائمة على التعاون والاحترام المتبادل."},{"t":"fact","kind":"قيم أتعلمها","text":"أعتز بوطني العربي وثقافته وتاريخه."}]},{"title":"جناحا الوطن العربي","src":[9],"blocks":[{"t":"map","img":"assets/b-map1.jpg","cap":"خريطة (١) دول الوطن العربي"},{"t":"split","a":{"h":"الجناح الآسيوي","big":"٢٨٪","sub":"من مساحة الوطن العربي","count":"١٢ دولة","items":["فلسطين","الأردن","لبنان","سوريا","العراق","الكويت","السعودية","البحرين","قطر","الإمارات","عُمان","اليمن"]},"b":{"h":"الجناح الإفريقي","big":"٧٢٪","sub":"من مساحة الوطن العربي","count":"١٠ دول","items":["مصر","السودان","ليبيا","تونس","الجزائر","المغرب","موريتانيا","جيبوتي","الصومال","جزر القُمر (تقع في المحيط الهندي)"]}},{"t":"fact","kind":"حقائق جغرافية","text":"الجزائر أكبر الدول العربية من حيث المساحة، والبحرين أصغرها."},{"t":"note","text":"يفصل البحر الأحمر بين جناحَي الوطن العربي (لاحظ الخريطة)."}]},{"title":"الموقع الجغرافي","src":[10],"blocks":[{"t":"terms","items":[{"term":"الموقع الجغرافي","def":"موقع الوطن العربي بالنسبة لليابس والماء."}]},{"t":"intro","text":"يقع وطننا العربي في وسط قارات العالم القديم (إفريقيا وآسيا وأوروبا)، ما جعله يحتل مكانة مهمة بين دول العالم، ويحيط به حدود طبيعية."},{"t":"compass","n":["البحر المتوسط","جبال طوروس"],"e":["جبال كردستان","جبال زاجروس","الخليج العربي","خليج عُمان"],"s":["المحيط الهندي","بحر العرب","الصحراء الكبرى"],"w":["المحيط الأطلنطي"]},{"t":"map","img":"assets/b-map2.jpg","cap":"خريطة (٢) الموقع الجغرافي للوطن العربي"},{"t":"fact","kind":"حقائق تاريخية","text":"الحدود الطبيعية للوطن العربي أثّرت في تاريخه وحضارته، ولم تمنع تواصُله مع العالم الخارجي."}]},{"title":"الموقع الفلكي","src":[11],"blocks":[{"t":"terms","items":[{"term":"الموقع الفلكي","def":"موقع الوطن العربي بالنسبة لخطوط الطول ودوائر العرض."}]},{"t":"stats","items":[{"v":"٢°","l":"جنوبًا","d":"أقصى امتداد لدوائر العرض جنوبًا."},{"v":"٣٧٫٥°","l":"شمالًا","d":"أقصى امتداد لدوائر العرض شمالًا."},{"v":"٦٠°","l":"شرقًا","d":"أقصى امتداد لخطوط الطول شرقًا."},{"v":"١٧°","l":"غربًا","d":"أقصى امتداد لخطوط الطول غربًا."}]},{"t":"flow","steps":[{"h":"الامتداد الفلكي","body":"يمتد الوطن العربي بين دائرتي عرض ٢° جنوبًا و٣٧٫٥° شمالًا، وخطي طول ٦٠° شرقًا و١٧° غربًا."},{"h":"النتيجة","body":"هذا الامتداد جعل معظمه يقع في نصف الكرة الشمالي، وأثّر على مناخه ونباتاته الطبيعية."}]},{"t":"fact","kind":"حقائق جغرافية","text":"دولة جزر القُمر هي الدولة العربية الوحيدة التي تقع خارج النطاق الفلكي للوطن العربي."}]},{"title":"أهمية موقع الوطن العربي","src":[11,12,13],"blocks":[{"t":"cards","items":[{"icon":"pyramid","h":"الأهمية الحضارية","body":"نشأت على أرض الوطن العربي العديد من الحضارات القديمة.","more":"منها الحضارة المصرية وحضارة العراق وحضارة اليمن."},{"icon":"mosque","h":"الأهمية الدينية","body":"الوطن العربي مَهْد الديانات السماوية الثلاث (اليهودية – المسيحية – الإسلام).","more":"تمثلها أماكن مقدّسة يقصدها الزائرون من جميع أنحاء العالم، مثل: بيت الله الحرام (الكعبة المشرّفة)، والمسجد الأقصى، وكنيسة المهد."},{"icon":"coin","h":"الأهمية الاقتصادية","body":"يتمتع الوطن العربي بأهمية اقتصادية كبيرة.","more":"• يُطِل على مسطحات مائية مهمة منها البحر المتوسط والبحر الأحمر والخليج العربي؛ مما جعله يتحكم في طرق التجارة العالمية.\n• اتساع مساحة الوطن العربي وتنوع الموارد الطبيعية به مثل المعادن والبترول والأقاليم المناخية والنباتية، مما يساعد على تنوع الإنتاج وزيادة النشاط الاقتصادي في الوطن العربي."},{"icon":"anchor","h":"الأهمية الإستراتيجية","body":"تحكّمه في ممرات مائية هامة.","more":"مثل قناة السويس – مَضِيق هرمز – مَضِيق باب المندب – مَضِيق جبل طارق، وهذا جعله ذا أهمية كبيرة وقت الحروب والصراعات الدولية."}]},{"t":"map","img":"assets/b-map3.jpg","cap":"خريطة (٣) الممرات المائية بالوطن العربي"},{"t":"fact","kind":"حقائق تاريخية","text":"الموقع الجغرافي المتميز والثروات الطبيعية للوطن العربي جعله مطمعًا لكثير من المحتلين عبر العصور المختلفة، حيث حاولوا السيطرة عليه من أجل نهب ثرواته والتحكم في موقعه وممرّاته الحيوية."}]},{"title":"تدريبات الدرس","src":[14,15],"ex":true,"blocks":[{"t":"pages","note":"تدريبات هذا الدرس معروضة من صفحات الكتاب الأصلية.","pages":[14,15]}]}],"blocks":21,"hasEx":true},{"id":"u1l2","unit":1,"n":2,"title":"تضاريس وطننا العربي","bookPages":[16,23],"icon":"mountain","objectives":["أحدّد عوامل تشكيل تضاريس الوطن العربي.","أقدّم أمثلة للتضاريس الرئيسية في الوطن العربي.","أستنتج العلاقة بين التضاريس وتنوع الأنشطة الاقتصادية في الوطن العربي.","أقدّر عظمة الخالق في تنوع تضاريس الوطن العربي."],"panels":[{"title":"كيف تكوّنت مظاهر السطح؟","src":[16,17],"blocks":[{"t":"intro","text":"تتنوع مظاهر سطح الوطن العربي ما بين مرتفعات ومنخفضات، تكوّنت منذ ملايين السنين بفعل عوامل باطنية وأخرى سطحية."},{"t":"split","a":{"h":"عوامل باطنية","sub":"نتج عنها تكوّن الجبال والهضاب","items":["الالتواءات","الانكسارات","البراكين"]},"b":{"h":"عوامل سطحية","sub":"ساهمت في تشكيل السهول والوديان","items":["الرياح","المياه"]}},{"t":"note","text":"هكذا أصبح لوطننا العربي تضاريس متنوعة أثّرت في حياة السكان وأنشطتهم."},{"t":"map","img":"assets/b-terrain.jpg","cap":"خريطة تضاريس الوطن العربي"}]},{"title":"الجبال","src":[17,18],"blocks":[{"t":"compare","head":["","الجبال الانكسارية","الجبال الالتوائية"],"rows":[["سبب النشأة","نشأت نتيجة حركات انكسارية في القشرة الأرضية.","نشأت نتيجة حركات التوائية تعرّضت لها الأرض."],["أمثلة","سلاسل جبال البحر الأحمر في (مصر والسودان)، وجبال الحجاز وعسير ومرتفعات اليمن في السعودية واليمن.","جبال زاجروس، وجبال عُمان، وجبال أطلس التي تمتد في ثلاث دول: تونس والجزائر والمغرب."]]},{"t":"fact","kind":"حقائق جغرافية","text":"في جبال أطلس أعلى جبل بالوطن العربي وهو جبل توبقال."},{"t":"cards","items":[{"icon":"pick","h":"أهمية الجبال","body":"للجبال أهمية كبيرة.","more":"استخدمها الإنسان في استخراج المعادن ومواد البناء، كما أنها تتميز بالمناظر الخلابة التي تجذب السياح للاستمتاع بها."}]}]},{"title":"الهضاب","src":[18],"blocks":[{"t":"intro","text":"تُعد الهضاب أكثر مظاهر السطح انتشارًا بالوطن العربي."},{"t":"cards","items":[{"icon":"plateau","h":"هضبة إفريقيا الشمالية","body":"أكبر هضاب الوطن العربي من حيث المساحة.","more":"تمتد من البحر الأحمر شرقًا إلى المحيط الأطلنطي غربًا، ومن البحر المتوسط شمالًا إلى وسط إفريقيا جنوبًا."},{"icon":"plateau","h":"هضاب الجناح الآسيوي","body":"تتميز شبه الجزيرة العربية بعدد من الهضاب.","more":"• هضبة بادية الشام في شمال شبه الجزيرة العربية.\n• هضبة نجد في الوسط.\n• هضبة حضرموت في الجنوب."}]},{"t":"map","img":"assets/b-plateaus.jpg","cap":"خريطة هضاب الوطن العربي"}]},{"title":"ظاهرات تضاريسية منتشرة بالهضاب","src":[19],"blocks":[{"t":"cards","items":[{"icon":"palm","h":"الواحات","body":"أرض منخفضة تقع وسط الصحراء، وتُزرَع باستخدام المياه الجوفية.","more":"ولذلك يعيش فيها السكان ويمارسون الزراعة، ومنها واحة سيوة في مصر، وواحة عين صالح في الجزائر."},{"icon":"dune","h":"الكثبان الرملية","body":"تجمّعات من الرمال الخفيفة تكوّنت بفعل التعرية الهوائية.","more":"تنتشر في المناطق الصحراوية مثل بحر الرمال العظيم بين مصر وليبيا."},{"icon":"valley","h":"الأودية الجافة","body":"تكوّنت بفعل التعرية المائية.","more":"تُستخدم كطريق للنقل والمواصلات واستخراج المياه الجوفية، ومنها: وادي العلاقي في مصر، ووادي الدواسر في السعودية."}]},{"t":"terms","items":[{"term":"التعرية المائية","def":"نحت الصخور ونقلها وإرسابها بواسطة المياه."},{"term":"التعرية الهوائية","def":"نحت الصخور ونقلها وإرسابها بواسطة الرياح."},{"term":"الأودية الجافة","def":"مَجارٍ كانت تملؤها المياه قديمًا ثم جفت."}]}]},{"title":"السهول","src":[20,21],"blocks":[{"t":"terms","items":[{"term":"السهول","def":"أراضٍ مستوية أو شبه مستوية السطح، وتنقسم في الوطن العربي إلى ثلاثة أنواع."}]},{"t":"map","img":"assets/b-plains.jpg","cap":"خريطة سهول الوطن العربي"},{"t":"cards","items":[{"icon":"river","h":"السهول الفيضية","body":"تكوّنت بفعل إرساب الأنهار للمواد العالقة.","more":"تتميز بخصوبة تربتها وتركز السكان فيها، مثل سهول نهر النيل في مصر والسودان، وسهول دجلة والفرات في العراق."},{"icon":"wave","h":"السهول الساحلية","body":"تتميز بتنوع الموارد والاستخدامات.","more":"فسهول البحر المتوسط تتميز بتربة خصبة صالحة للزراعة، وسهول البحر الأحمر والخليج العربي غنية بالثروات المعدنية ومصادر الطاقة."},{"icon":"dune","h":"السهول الصحراوية","body":"تكوّنت بفعل الرياح عن طريق النحت أو الترسيب.","more":"تتنوع السهول ما بين رملية وصخرية، وتتميز بندرة الغطاء النباتي الطبيعي."}]},{"t":"flow","steps":[{"h":"تنوع مظاهر السطح","body":"ساعد تنوع مظاهر السطح في الوطن العربي على تنوع الموارد."},{"h":"تنوع الأنشطة الاقتصادية","body":"مثل: الزراعة والصيد والتعدين والسياحة والصناعة."}]},{"t":"fact","kind":"قيم أتعلمها","text":"تنوع التضاريس يدعو إلى تأمل قدرة الله في الخلق وتقبّل الاختلاف والتنوع."}]},{"title":"نص إثرائي: واحة سيوة","src":[22],"blocks":[{"t":"intro","text":"تُعد واحة سيوة من الواحات المميزة في مصر والوطن العربي."},{"t":"cards","items":[{"icon":"sun","h":"الطقس الجاف","body":"تمتاز بالطقس الجاف الذي يخلو من الرطوبة.","more":"مما يساعد على علاج بعض أمراض الجهاز التنفسي."},{"icon":"dune","h":"الرمال البيضاء الساخنة","body":"تنتشر بها الرمال البيضاء الساخنة.","more":"تساعد في علاج كثير من الأمراض الروماتيزمية وآلام المفاصل."},{"icon":"drop","h":"عيون المياه الكبريتية","body":"تتميز بعيون المياه الكبريتية.","more":"تُستخدم في علاج بعض الأمراض الجلدية."}]}]},{"title":"تدريبات الدرس","src":[22,23],"ex":true,"blocks":[{"t":"pages","note":"تدريبات هذا الدرس معروضة من صفحات الكتاب الأصلية.","pages":[22,23]}]}],"blocks":20,"hasEx":true},{"id":"u1l3","unit":1,"n":3,"title":"وطننا العربي (المناخ - النبات الطبيعي)","bookPages":[24,29],"icon":"sun","objectives":["أفسّر أسباب اختلاف الأحوال المناخية بين الدول العربية.","أحدّد أهم الأقاليم المناخية في الوطن العربي.","أقارن بين خصائص الأقاليم المناخية في الوطن العربي.","أستنتج أسباب تنوع النباتات في الوطن العربي.","أوضّح تأثير المناخ على الأنشطة الاقتصادية في الوطن العربي."],"panels":[{"title":"العوامل المؤثرة في مناخ وطننا العربي","src":[24,25],"blocks":[{"t":"intro","text":"تنوع المناخ في الوطن العربي أدى إلى تنوع النباتات الطبيعية والحيوانات البرية والأنشطة الاقتصادية المختلفة، مما يعزز تحقيق التكامل بين دول الوطن العربي."},{"t":"cards","items":[{"icon":"globe","h":"١ - الموقع الفلكي","body":"المناطق القريبة من دائرة الاستواء تكون أعلى حرارة.","more":"تقل درجات الحرارة كلما ابتعدنا عن دائرة الاستواء شمالًا أو جنوبًا؛ لذلك فمعظم الوطن العربي يتميز بالمناخ الحار ما عدا الأجزاء الشمالية فتتميز بالمناخ المعتدل."},{"icon":"wave","h":"٢ - الموقع بالنسبة للمسطحات المائية","body":"المناطق القريبة من المسطحات المائية (البحار – المحيطات) تتميز باعتدال المناخ.","more":"أما المناطق البعيدة عن المسطحات المائية (المناطق الداخلية) فتكون شديدة الحرارة صيفًا وشديدة البرودة شتاءً."},{"icon":"mountain","h":"٣ - مظاهر السطح","body":"تؤثر في مناخ الوطن العربي من حيث الارتفاع واتجاه الكتل الجبلية.","more":"• الارتفاع: كلما ارتفعنا ١٥٠ مترًا عن سطح البحر تنخفض درجة الحرارة درجة مئوية واحدة؛ ولذلك تغطّي الثلوج بعض القمم العالية مثل جبال لبنان.\n• اتجاه الكتل الجبلية: يؤثر في توزيع كمية المطر؛ لذلك نجد سفوح (جوانب) الجبال المواجهة للرياح المحملة ببخار الماء تكون أغزر مطرًا من السفوح (الجوانب) الداخلية مثل جبال أطلس."}]},{"t":"fact","kind":"قيم أتعلمها","text":"الحفاظ على الحياة النباتية والحيوانية مسئولية بيئية."}]},{"title":"الأقاليم المناخية في الوطن العربي","src":[26,27],"blocks":[{"t":"terms","items":[{"term":"الإقليم المناخي","def":"مساحة من الأرض لها نفس الخصائص المناخية من حيث الحرارة والمطر."}]},{"t":"map","img":"assets/b-climate.jpg","cap":"خريطة الأقاليم المناخية في الوطن العربي"},{"t":"compare","head":["","إقليم البحر المتوسط","الإقليم الصحراوي","الإقليم المداري"],"rows":[["الموقع","يمتد في الأجزاء الشمالية للوطن العربي.","يقع بين إقليم البحر المتوسط شمالًا والإقليم المداري جنوبًا.","يقع في جنوب الوطن العربي."],["المناخ","ارتفاع درجة الحرارة صيفًا، واعتدالها وسقوط الأمطار شتاءً.","ارتفاع شديد في درجة الحرارة صيفًا (خاصة في النهار)، وانخفاض شديد في درجة الحرارة شتاءً (خاصة في الليل).","ارتفاع درجة الحرارة وسقوط الأمطار صيفًا، واعتدال الحرارة وجفاف المناخ شتاءً."],["النبات الطبيعي","الغابات المعتدلة فوق المنحدرات الجبلية لغزارة الأمطار، ومن أهم أشجارها الزيتون والأرز. وتنمو به الحشائش المعتدلة (الإستبس) وتزدهر شتاءً وتجف صيفًا.","يختلف حسب كمية المطر: تنمو الأعشاب القصيرة في المناطق قليلة المطر، وتنمو النباتات الشوكية في المناطق نادرة المطر.","الغابات المدارية وتكثر بها أشجار السنط التي يُستخرج منها الصمغ العربي، وحشائش السافانا التي تتدرج في الطول حسب كمية المطر."],["الحيوان","تُربَّى على حشائش الإستبس الأغنام والماعز.","الزواحف والإبل والغزلان.","الزراف – الأسود – النمور – الأفيال، وتعيش جميعها في مناطق السافانا."]]}]},{"title":"تأثير المناخ على الأنشطة الاقتصادية","src":[27],"blocks":[{"t":"intro","text":"تنوع المناخ في الوطن العربي له تأثير كبير على الأنشطة الاقتصادية."},{"t":"chips","items":["تنوع المحاصيل الزراعية من مكان لآخر.","تنشيط السياحة البيئية.","تحقيق التكامل بين الدول العربية من خلال تبادل المحاصيل والمنتجات."]},{"t":"fact","kind":"حقائق تاريخية","text":"المصريون القدماء أظهروا تقديرًا للطبيعة وحرصوا على عدم إلحاق الضرر بها."}]},{"title":"تغيّر المناخ والنبات الطبيعي","src":[28],"blocks":[{"t":"flow","steps":[{"h":"تنوع المناخ","body":"يتنوع المناخ في الوطن العربي بين الصحراوي والمداري والمعتدل، ويؤثر هذا التنوع بشكل مباشر على توزيع النبات الطبيعي."},{"h":"أضرار تغيّر المناخ","body":"تسبّب تغيّر المناخ في أضرار كبيرة للنبات في وطننا العربي، حيث جفت التربة في بعض المناطق واختفت النباتات، كما أدت درجات الحرارة المرتفعة إلى حرائق الغابات."},{"h":"واجبنا","body":"علينا أن نعتني بالبيئة، من خلال زراعة المزيد من الأشجار، والحد من التلوث؛ لنحافظ على أرضنا ونحمي مستقبلنا."}]}]},{"title":"تدريبات الدرس","src":[28,29],"ex":true,"blocks":[{"t":"pages","note":"تدريبات هذا الدرس معروضة من صفحات الكتاب الأصلية.","pages":[28,29]}]}],"blocks":11,"hasEx":true},{"id":"u1l4","unit":1,"n":4,"title":"التحديات البيئية في وطننا العربي","bookPages":[30,36],"icon":"drop","objectives":["أتعرّف جهود بعض الدول العربية لحماية البيئة الطبيعية.","أفسّر أسباب بعض المشكلات البيئية في الوطن العربي.","أستنتج الآثار المترتبة على المشكلات البيئية في الوطن العربي.","أقترح أكبر عدد من الوسائل للحفاظ على البيئة وتنميتها بشكل مستدام في الوطن العربي."],"panels":[{"title":"التغير المناخي والمشكلات البيئية","src":[30],"blocks":[{"t":"intro","text":"بسبب التغيّرات المناخية أصبح وطننا العربي يواجه العديد من المشكلات البيئية، منها الجفاف وندرة المياه العذبة والتصحر وتلوث الهواء والسيول، ويؤثر ذلك على مستقبل التنمية والاستقرار في المنطقة."},{"t":"terms","items":[{"term":"التغير المناخي","def":"هو ارتفاع في درجات الحرارة وتغيير في مستويات المطر، عن المعتاد يؤدي إلى موجات جفاف، وحرائق غابات، وانقراض نباتات."}]},{"t":"fact","kind":"قيم أتعلمها","text":"الحفاظ على البيئة من التلوث يساهم في التخفيف من آثار التغير المناخي وارتفاع درجة الحرارة."}]},{"title":"ندرة المياه العذبة","src":[30,31],"blocks":[{"t":"duo","a":{"h":"الأسباب","items":["قلة سقوط الأمطار.","سوء إدارة الموارد المائية باستخدام طرق الري التقليدية (القديمة).","زيادة عدد السكان في بعض الدول العربية."]},"b":{"h":"طرق المواجهة","items":["ترشيد استهلاك المياه.","تحسين شبكات المياه والصرف الصحي.","حملات توعية للحفاظ على المياه.","استخدام أساليب جديدة في الري مثل الري بالرش والتنقيط."]}}]},{"title":"الجفاف","src":[31],"blocks":[{"t":"terms","items":[{"term":"الجفاف","def":"نقص كمية الأمطار خلال فترة زمنية محددة."}]},{"t":"duo","a":{"h":"ما يترتب عليه","items":["نقص الغذاء.","التأثير بالسلب على النشاط الزراعي والرعوي.","انتشار الأمراض وسوء التغذية."]},"b":{"h":"طرق المواجهة","items":["إعادة تدوير المياه.","تطوير شبكات الري.","ترشيد استهلاك المياه."]}},{"t":"fact","kind":"حقائق تاريخية","text":"عانت الصومال من أكبر موجة جفاف ونقص في الغذاء وحدوث مجاعة لأكثر من مليون إنسان."}]},{"title":"التصحر","src":[32],"blocks":[{"t":"terms","items":[{"term":"التصحر","def":"تناقص قدرة الأراضي الزراعية على الإنتاج."}]},{"t":"intro","text":"يغطي نسبة كبيرة من مساحة الوطن العربي، وترتّب عليه تدهور الأراضي الزراعية."},{"t":"chips","h":"أسباب التصحر","items":["زحف الكثبان الرملية.","قطع الأشجار.","تناقص الأمطار والمياه الجوفية.","الرعي الجائر للحيوانات.","التوسع العمراني."]}]},{"title":"تلوث الهواء","src":[32],"blocks":[{"t":"duo","a":{"h":"الأسباب","items":["العواصف الرملية.","زيادة النشاط الصناعي الملوث للبيئة.","الاعتماد على مصادر الطاقة غير المتجددة."]},"b":{"h":"طرق المواجهة","items":["الاعتماد على الطاقة المتجددة.","زيادة المساحات الخضراء.","استخدام النقل المستدام.","إعادة تدوير النفايات."]}}]},{"title":"السيول","src":[33],"blocks":[{"t":"terms","items":[{"term":"السيول","def":"أمطار غزيرة وفجائية تتجمع وتتدفق بسرعة في الأودية."}]},{"t":"duo","a":{"h":"لماذا تشكّل تهديدًا كبيرًا؟","items":["الأضرار التي تُلحِقها بالبنية التحتية.","إتلاف المحاصيل الزراعية.","الخسائر الفادحة في الأرواح والممتلكات.","انتشار الأمراض والأوبئة."]},"b":{"h":"طرق المواجهة","items":["استخدام التكنولوجيا في التنبؤ بالأخطار البيئية (السيول).","بناء سدود للاستفادة منها في الزراعة.","إنشاء مخرات لتصريف السيول.","تطوير البنية التحتية."]}},{"t":"fact","kind":"حقائق تاريخية","text":"قام المصريون القدماء بإنشاء مخرات السيول (مَجارٍ مائية) لتصريف مياه الأمطار لحماية المعابد والمقابر."}]},{"title":"مواجهة التغيرات المناخية","src":[33,34],"blocks":[{"t":"intro","text":"التغيرات المناخية لها تأثير كبير على المشكلات البيئية والزيادة من حدتها، فما يشهده الوطن العربي من ارتفاع درجة الحرارة وجفاف وسيول وارتفاع مستوى سطح البحر وانتشار الأمراض من نتائج التغيرات المناخية."},{"t":"chips","h":"إجراءات عاجلة للحد من آثارها","items":["الاعتماد على مصادر الطاقة المتجددة.","تفعيل القوانين لمواجهة التغيرات البيئية.","حماية الغابات وزيادة مساحة الأراضي الخضراء."]},{"t":"cards","items":[{"icon":"tree","h":"مصر","body":"أطلقت مبادرة زراعة ١٠٠ مليون شجرة في كل أنحاء مصر.","more":"وذلك لتحسين الهواء، وتقليل التلوث، وتجميل البيئة، ومواجهة التغيرات المناخية."},{"icon":"tree","h":"السعودية","body":"أطلقت مبادرة زراعة ٤٥٠ مليون شجرة في الدول العربية.","more":"للحد من التلوث ومواجهة التغير المناخي، كما تعمل السعودية على إنشاء مدينة نيوم الخضراء، وهي مدينة تعتمد على الطاقة النظيفة وتحافظ على البيئة."}]},{"t":"fact","kind":"قيم أتعلمها","text":"الحفاظ على البيئة مسئولية مشتركة تقع على عاتق الفرد والمجتمع."}]},{"title":"نصوص إثرائية","src":[35],"blocks":[{"t":"cards","items":[{"icon":"dune","h":"التصحر","body":"يسبب التصحر اختفاء النباتات وتدهور الأراضي الزراعية.","more":"بسبب قلة الأمطار وقطع الأشجار والرعي الجائر."},{"icon":"wave","h":"السيول","body":"تحدث السيول فجأة بعد سقوط أمطار غزيرة، فتجرف التربة والمباني وتتلف المحاصيل.","more":"وتزداد خطورتها في المناطق التي لا توجد فيها سدود أو شبكات صرف جيدة؛ لذلك تبني الدول العربية السدود وتطور البنية التحتية لتقليل أضرار السيول."},{"icon":"factory","h":"تلوث الهواء","body":"يزداد تلوث الهواء في المدن الكبرى بسبب عوادم السيارات ودخان المصانع وحرق النفايات.","more":"ويؤثر هذا التلوث على صحة الإنسان؛ فيسبّب أمراضًا تنفسية، كما يؤذي النباتات والحيوانات، ويؤدي إلى تغيرات في المناخ على المدى الطويل."}]}]},{"title":"تدريبات الدرس","src":[35,36],"ex":true,"blocks":[{"t":"pages","note":"تدريبات هذا الدرس معروضة من صفحات الكتاب الأصلية.","pages":[35,36]}]}],"blocks":20,"hasEx":true},{"id":"u2l1","unit":2,"n":1,"title":"شبه الجزيرة العربية (قبل وبعد ظهور الإسلام)","bookPages":[42,49],"icon":"kaaba","objectives":["أصف ملامح الحياة في شبه الجزيرة العربية قبل ظهور الإسلام.","أقارن بين الأحوال السياسية والاجتماعية والاقتصادية لسكان شبه الجزيرة العربية قبل ظهور الإسلام.","أتعرّف نشأة النبي محمد ﷺ وبعثته.","أوضح الصعوبات التي واجهت النبي ﷺ في نشر الدعوة."],"panels":[{"title":"الحياة السياسية والاقتصادية قبل الإسلام","src":[42,43],"blocks":[{"t":"intro","text":"هيا بنا لنسافر معًا عبر الزمن لنكتشف كيف كانت حياة العرب في شبه الجزيرة العربية قبل ظهور الإسلام."},{"t":"cards","items":[{"icon":"flag","h":"١- الحياة السياسية","body":"كان النظام القَبَلي هو النظام السائد في شبه الجزيرة العربية قبل ظهور الإسلام.","more":"وذلك بسبب الحروب والخلافات بين القبائل، ومن أشهر القبائل في ذلك الوقت قبيلة قريش."},{"icon":"coin","h":"٢- الحياة الاقتصادية","body":"مارَس سكان شبه الجزيرة العربية عديدًا من الحِرَف.","more":"• رعي الأغنام: أكثر الحِرَف انتشارًا.\n• الصناعة: تميز العرب بصناعة السيوف والرماح والأواني الفخارية.\n• التجارة: عمل العرب بالتجارة، وكان أهل مكة أعظمهم مكانة تجارية؛ لأنهم نظموا رحلتي الشتاء والصيف."}]},{"t":"terms","items":[{"term":"القبيلة","def":"جماعة من الناس ينتمون إلى أصل ونسب واحد، ولهم عادات وتقاليد مشتركة."},{"term":"النظام القَبَلي","def":"نظام يتكون من قبائل متفرقة، ولكل قبيلة شيخ يحكمها."}]},{"t":"map","img":"assets/b-u2-trade.jpg","cap":"خريطة (١) طرق التجارة في مكة — رحلة الصيف ورحلة الشتاء"},{"t":"ask","kind":"ألاحظ وأجيب","q":["حدد اتجاه رحلتي الشتاء والصيف."]}]},{"title":"الحياة الاجتماعية والدينية والثقافية","src":[43,44],"blocks":[{"t":"intro","text":"٣- الحياة الاجتماعية: كان المجتمع في شبه الجزيرة العربية قبل الإسلام ينقسم إلى طبقات اجتماعية مختلفة، وكان الناس يعيشون في قبائل لها عادات وتقاليد متنوعة."},{"t":"chips","h":"طبقات المجتمع","items":["طبقة الفقراء والعبيد.","طبقة صغار التجار والحرفيين.","طبقة الأغنياء من التجار وأصحاب الأراضي والمراعي."]},{"t":"duo","a":{"h":"العادات الحسنة","items":["الشجاعة","الكرم","الصبر","الوفاء بالعهد"]},"b":{"h":"العادات السيئة","items":["وأد البنات","الأخذ بالثأر","شرب الخمر","لعب الميسر"]}},{"t":"cards","items":[{"icon":"mosque","h":"٤- الحياة الدينية","body":"كانت شبه الجزيرة العربية مهدًا لكثير من الأنبياء، منهم: هود وصالح وشُعيب؛ لذلك عرَف أهلها عبادة الله الواحد.","more":"لكن مع مرور الوقت ابتعد بعض الناس عن عبادة الله، وظهرت بينهم عبادات غير سماوية مثل عبادة الأصنام."},{"icon":"scroll","h":"٥- الحياة الثقافية","body":"اشتهر العرب بالشِّعر والخطابة.","more":"وكانت الأسواق مكانًا لتنافس الشعراء والخطباء، مثل سوق عُكاظ وسوق ذي المَجاز."}]},{"t":"ask","kind":"أقرأ وأجيب","q":["أشهر القبائل في شبه الجزيرة العربية قبل الإسلام ……","أكثر الحرف انتشارًا في شبه الجزيرة العربية قبل الإسلام ……"]},{"t":"ask","kind":"أتعلم وأطبق","q":["لو كنتَ شيخ قبيلة، ما العادات التي تحرص على نشرها بين أفرادها؟"]},{"t":"ask","kind":"أفهم وأجيب","q":["اذكر مجالات استخدام العرب للأسواق."]},{"t":"note","text":"نتيجة لما شهدته شبه الجزيرة العربية قبل ظهور الإسلام من البعد عن عبادة الله الواحد الأحد، كانوا في حاجة إلى ظهور نبي ليُرشِد الناس إلى عبادة الله الواحد الأحد، وينشر العدل والمساواة بينهم."}]},{"title":"ميلاد النبي محمد ﷺ ونشأته","src":[44,45,46],"blocks":[{"t":"stats","items":[{"v":"١٢","u":"ربيع الأول","l":"يوم الميلاد","d":"وُلد النبي محمد ﷺ في ١٢ من ربيع الأول الموافق لعام ٥٧٠م في مكة."},{"v":"٥٧٠م","l":"عام الفيل","d":"يُعرَف عام مولده بعام الفيل؛ لأن أبرهة الحبشي حاول هدم الكعبة في هذا العام مستخدمًا الفيلة."}]},{"t":"intro","text":"وكان يتيمًا بعد أن تُوفي والده عبد الله قبل ولادته، أما أمُّه فهي آمنة بنت وهب."},{"t":"timeline","cap":"خط زمني لسيرة النبي ﷺ","items":[{"n":"١","text":"عاش النبي محمد ﷺ في ديار بني سعد عند مرضعته السيدة حليمة السعدية، واكتسب منهم فصاحة اللسان وقوة البنيان ورجاحة العقل."},{"n":"٢","text":"عاش النبي محمد ﷺ مع أمه آمنة بنت وهب حتى تُوفيت وهو في السادسة من عمره."},{"n":"٣","text":"تولى جده عبد المطلب رعايته، ثم توفي عندما كان النبي محمد ﷺ في عمر ٨ سنوات."},{"n":"٤","text":"عاش النبي محمد ﷺ في بيت عمه أبي طالب، وعمل برعي الأغنام لكي لا يكون عبئًا على عمه، وفي شبابه عمل بالتجارة ولُقِّب بالصادق الأمين."},{"n":"٥","text":"تزوَّج من السيدة خديجة بنت خويلد رضي الله عنها وأنجَب منها من الذكور اثنين، ومن الإناث أربعًا."},{"n":"٦","text":"نزل عليه سيدنا جبريل بالوحي وهو يتعبَّد في غار حراء في إحدى ليالي شهر رمضان."},{"n":"٧","text":"أخبَرَه ورقة بن نوفل ابن عم السيدة خديجة أنه نبي هذه الأمَّة."}]},{"t":"terms","items":[{"term":"الوحي","def":"تعاليم صادرة من الله عز وجل إلى الأنبياء بواسطة جبريل عليه السلام."}]},{"t":"fact","kind":"حقائق تاريخية","text":"اكتسب النبي ﷺ عدة صفات من حرفة الرعي مثل الصبر والتواضع والرحمة والشجاعة."},{"t":"ask","kind":"أتعلم وأطبق","q":["صمم بطاقة تعريفية بالنبي محمد ﷺ من خلال النص السابق، واعرضها على معلمك."]},{"t":"ask","kind":"ألاحظ وأحلل","q":["ما الصفات التي اكتسبها النبي ﷺ في ديار بني سعد؟","دلل: حياة النبي ﷺ علَّمتنا الاعتماد على النفس."]}]},{"title":"المرحلة الأولى: سِرِّيَّة الدعوة","src":[46],"blocks":[{"t":"stats","items":[{"v":"٣","u":"سنوات","l":"مدة الدعوة السرية","d":"استغرقت ثلاث سنوات، بدأ النبي ﷺ بدعوة أهل بيته وأصحابه المقرَّبين سرًّا؛ خوفًا من أذى قريش."}]},{"t":"chips","h":"من أبرز مَن آمَنوا في هذه المرحلة","items":["أبو بكر الصدِّيق رضي الله عنه","السيدة خديجة رضي الله عنها","علي بن أبي طالب رضي الله عنه"]},{"t":"note","text":"اتخذ النبي ﷺ من دار الأرقم بن أبي الأرقم مدرسة ليعلم فيها المسلمين مبادئ الدين الإسلامي."}]},{"title":"المرحلة الثانية: الدعوة الجهرية دون مواجهة","src":[47],"blocks":[{"t":"intro","text":"أذِن الله للنبي محمد ﷺ بإعلان الدعوة بعد ٣ سنوات من الدعوة السرية، فخافت قريش على مكانتها ونفوذها بين القبائل."},{"t":"duo","a":{"h":"ما قامت به قريش","items":["إيذاء النبي ﷺ واتهامه بالسِّحر والجنون.","التفاوض معه وإغرائه بالمال والزعامة والسلطة ولكنه رفض.","تعذيب وإيذاء المسلمين.","حصار المسلمين ومقاطعتهم (عدم البيع والشراء منهم)."]},"b":{"h":"رد فعل النبي ﷺ على إيذاء قريش","items":["حث المسلمين على الصبر والتحمل.","أمَر أصحابه بالهجرة إلى الحبشة؛ لأن ملكها النجاشي كان عادلًا لا يُظلَم عنده أحد.","حاول نشر الدعوة في الطائف، لكن أهلها قابَلوه بالأذى فعاد إلى مكة."]}},{"t":"note","text":"استمر النبي ﷺ في دعوة القبائل القادمة إلى مكة في موسم الحج، واستجاب له وفد من أهل يثرب ودخلوا الإسلام."},{"t":"fact","kind":"قيم أتعلمها","text":"يدعو الإسلام إلى التسامح مع الآخرين، على الرغم من اختلاف الثقافات والمعتقدات."},{"t":"fact","kind":"تعلمت","text":"لقد تعلمت أنه بالصبر والإصرار أستطيع التغلب على أي صعوبات قد تواجهني في الحياة."},{"t":"ask","kind":"أفكر وأستنتج","q":["لماذا اختار النبي محمد ﷺ أن تكون الدعوة في بدايتها سِرِّية؟","فسر شدة إيذاء قريش للمسلمين بعد الجهر بالدعوة.","ما الدروس المستفادة من تعامل النبي ﷺ خلال المرحلة الجهرية للدعوة؟"]}]},{"title":"تدريبات الدرس","src":[48,49],"ex":true,"blocks":[{"t":"ask","kind":"لاحظ وأجب","q":["أمامك مجموعة صور تعبّر عن بعض الأنشطة الاقتصادية التي انتشرت في شبه الجزيرة العربية قبل الإسلام، اكتب اسم النشاط الاقتصادي أسفل كل صورة، ثم حدد النشاط الأكثر انتشارًا. (الصور بالكتاب المدرسي صفحة ٤٨)"]},{"t":"ask","kind":"فكر واكتب","q":["«تحلَّى العرب قبل الإسلام ببعض القيم الأخلاقية الحميدة»، اذكر اثنتين منها ثم اذكر موقفًا حدث لك تحلَّيت فيه بإحدى تلك القيم."]},{"t":"ask","kind":"ابحث واكتب","q":["ابحث في مصادر التعلم المختلفة، واكتب سطرين عن «سبب تسمية النبي ﷺ بالصادق الأمين».","في رأيك، ما تأثير انتشار سلوكيات الصدق والأمانة في المجتمع؟"]},{"t":"ask","kind":"أكمل الجمل الآتية بما يناسبها من كلمات","q":["عمل العرب قديمًا بالصناعة ومنها صناعة ……","كانت أول هجرة للمسلمين إلى ……","عمل النبي ﷺ في شبابه بحرفة ……","تولى رعاية النبي ﷺ بعد وفاة أمه ……"]},{"t":"ask","kind":"اكتب (صواب) أو (خطأ)","q":["عرَفت شبه الجزيرة العربية التوحيد قبل مجيء النبي محمد ﷺ.","للشعر والخطابة مكانة كبيرة عند العرب قبل ظهور الإسلام.","بدأت قريش في إيذاء النبي ﷺ في المرحلة السرية للدعوة.","كانت الهجرة إلى الحبشة بأمر من النبي ﷺ."]},{"t":"ask","kind":"بم تفسر…؟","q":["ازدهار التجارة في مكة قديمًا.","عمل النبي ﷺ في صغره بحرفة الرعي.","الأهمية الثقافية والدينية لشبه الجزيرة العربية قبل الإسلام."]},{"t":"ask","kind":"أيِّد بالأدلة صحة العبارات التالية","q":["لم تقتصر أسواق العرب قديمًا على التجارة.","لم يجتمع العرب على عبادة واحدة قبل الإسلام.","تحلَّى النبي ﷺ بالأخلاق الحميدة في التعامل مع قريش."]},{"t":"ask","kind":"ما النتائج المترتبة على…؟","q":["سيادة النظام القبلي في شبه الجزيرة العربية قبل الإسلام.","عمل النبي ﷺ في التجارة.","دعوة النبي لبعض القبائل التي تَفِد إلى مكة في موسم الحج للدخول في الإسلام."]},{"t":"ask","kind":"هيا نستعد للدرس القادم","q":["لماذا هاجر النبي ﷺ من مكة إلى المدينة؟"]}]}],"blocks":38,"hasEx":true},{"id":"u2l2","unit":2,"n":2,"title":"الهجرة وعالمية الدعوة","bookPages":[50,55],"icon":"camel","objectives":["أشرح أهمية الهجرة إلى يثرب.","أفسّر أهمية أسس بناء الدولة الإسلامية.","أتعرّف بعض غزوات الرسول ﷺ.","أستنتج قيم المواطنة من صحيفة المدينة."],"panels":[{"title":"الهجرة إلى يثرب","src":[50],"blocks":[{"t":"intro","text":"بعد أن اشتد أذى قريش للمسلمين في مكة، أذِن النبي ﷺ لأصحابه بالهجرة إلى يثرب، فتركوا خلفهم أموالهم ومنازلهم، هربًا من التعذيب والاضطهاد. لكن «قريش» خافت من هجرة المسلمين إلى يثرب، فاجتمع زعماؤها في دار الندوة ليتآمروا على قتل النبي ﷺ؛ ليمنعوه من الهجرة."},{"t":"ask","kind":"ألاحظ وأجيب","q":["لماذا هاجر المسلمون إلى يثرب؟ توقع كيف استقبل أهل يثرب الرسول ﷺ وأصحابه."]},{"t":"flow","h":"خطة الرسول ﷺ للهجرة","steps":[{"h":"التجهيز","body":"طلب النبي ﷺ من أبي بكر الصدِّيق تجهيز ناقتين للهجرة، وخرجا معًا ليلًا في سِرِّية تامة."},{"h":"غار ثَوْر","body":"اختبأ النبي ﷺ وصاحبه في غار ثَوْر ثلاثة أيام، وكانت عناية الله تحرسهما من أعيُن المشركين."},{"h":"الدليل الأمين","body":"استأجر النبي ﷺ رجلًا أمينًا يعرف طرق الصحراء، فسارا وسلكا معه طريقًا غير مألوف؛ حتى لا يُكتشف أمرهما."},{"h":"الوصول إلى يثرب","body":"وبعد رحلة شاقة وطويلة وصلا إلى يثرب، وهناك استقبلهم أهلها بالفرح والسرور."}]},{"t":"ask","kind":"أبحث وأتعلم","q":["استنتج العوامل التي ساعدت على نجاح هجرة الرسول ﷺ، وكيف تستفيد منها في حياتك."]}]},{"title":"أسس بناء الدولة الإسلامية في المدينة","src":[51],"blocks":[{"t":"cards","items":[{"icon":"mosque","h":"بناء المسجد","body":"أول أعمال النبي ﷺ بعد وصوله إلى المدينة.","more":"ليكون مركزًا للعبادة ومَقرًّا للحكم. (أول مسجد في الإسلام: مسجد قباء)."},{"icon":"scroll","h":"وضع صحيفة المدينة","body":"وضعها النبي ﷺ لتحديد حقوق المسلمين وغير المسلمين.","more":"وأكدت على التعايش السلمي."},{"icon":"hands","h":"المؤاخاة بين المهاجرين والأنصار","body":"حرَص النبي ﷺ على تقوية وحدة المسلمين.","more":"لنشر المحبة والتعاون، وبناء مجتمع إسلامي قوي ومتماسك."},{"icon":"shield","h":"تأمين الدولة وحمايتها","body":"كوَّن النبي ﷺ جيشًا قويًّا، ودرَّبه وسلَّحه.","more":"لتأسيس الدولة والدفاع عنها."}]},{"t":"terms","items":[{"term":"المهاجرون","def":"المسلمون الذين تركوا ديارهم وأموالهم في مكة وهاجروا إلى المدينة."},{"term":"الأنصار","def":"المسلمون الذين نصروا النبي ﷺ من أهل المدينة."}]},{"t":"ask","kind":"أقرأ وأجيب","q":["وضح دور كل من (المسجد – الجيش) في بناء الدولة الإسلامية في المدينة.","ما النتائج المترتبة على وضع صحيفة المدينة؟"]}]},{"title":"المرحلة الثالثة: مواجهة المعتدين على الدعوة","src":[51,52],"blocks":[{"t":"intro","text":"بدأت مرحلة جديدة من الدعوة بعد تأسيس الدولة الإسلامية في المدينة، فخاض النبي ﷺ الغزوات وأرسل السرايا لحماية الدولة."},{"t":"terms","items":[{"term":"الغزوة","def":"خروج الجيش للقتال بقيادة النبي ﷺ."},{"term":"السَّرِيَّة","def":"خروج الجيش للقتال دون النبي ﷺ."}]},{"t":"timeline","cap":"غزوات النبي ﷺ","items":[{"n":"٢ هـ","h":"غزوة بدر","text":"كانت بين المسلمين وقريش، وسميت بهذا الاسم لأن الصحابي الحُباب بن المُنذِر أشار على النبي ﷺ أن يعسكر عند أقرب بئر لبدر؛ لمنع الماء عن المشركين، وانتهت بانتصار المسلمين رغم قلة عددهم عن قريش."},{"n":"٣ هـ","h":"غزوة أُحُد","text":"كانت بين المسلمين وقريش، وفي بداية المعركة انتصر المسلمون، ولكن خالف بعض الرماة أمر النبي ﷺ وتركوا أماكنهم لجمع الغنائم، فتحول نصر المسلمين إلى هزيمة."},{"n":"٥ هـ","h":"غزوة الخندق","text":"كانت بين المسلمين وقريش وحلفائها، وسميت بهذا الاسم لأن الصحابي سلمان الفارسي اقترح على النبي ﷺ حفر الخندق حول المدينة لمنع قريش وحلفائها من الوصول إلى المسلمين، وهبت رياح شديدة فغادرت قريش وانتهت بانتصار المسلمين على قريش وحلفائها دون قتال."}]},{"t":"ask","kind":"أفكر وأستنتج","q":["ما أسباب هزيمة المسلمين في غزوة أُحُد؟"]},{"t":"ask","kind":"أفكر وأحلل","q":["أسَّس النبي ﷺ دولته على مبدأ الشورى. دلل على صحة العبارة."]}]},{"title":"المرحلة الرابعة: عالمية الدعوة","src":[52,53],"blocks":[{"t":"intro","text":"عندما خرج النبي محمد ﷺ مع أصحابه لأداء العمرة منعته قريش من دخول مكة، فدارت مفاوضات بين الطرفين، وانتهت بصلح الحُدَيْبية."},{"t":"timeline","cap":"من الصلح إلى الفتح","items":[{"n":"٦ هـ","h":"صلح الحُدَيْبية","text":"عُقد بين المسلمين وقريش، ينص على وقف الحرب بين الطرفين لمدة ١٠ سنوات، ومن ثم بدأ النبي ﷺ بإرسال الرسل إلى ملوك العالم يدعوهم إلى الإسلام، وبدأت مرحلة عالمية الدعوة."},{"n":"٨ هـ","h":"فتح مكة","text":"توجه النبي ﷺ بجيش كبير إلى مكة، حيث نقضت قريش صلح الحديبية باعتدائها على قبيلة خزاعة، وهي من حلفاء المسلمين، وكانت النتيجة فتح مكة دون قتال وتحطيم الأصنام."}]},{"t":"fact","kind":"معلومة إثرائية","text":"كان لأم سلمة رضي الله عنها دور حكيم يوم الحديبية، حين تأخر المسلمون في تنفيذ أمر النبي ﷺ، فأشارت عليه أن يبدأ بنفسه بالحلق والذبح دون أن يكلم أحدًا، فلما فعل، اقتدى به الصحابة، مما أدى إلى تهدئة الموقف وحل المشكلة."},{"t":"fact","kind":"قيم أتعلمها","text":"ضرب النبي ﷺ أروع الأمثلة في التسامح والعفو عند فتح مكة حينما قال لأهل مكة: «اذهبوا فأنتم الطُّلَقاء»."},{"t":"fact","kind":"حقائق جغرافية","text":"تُعد مكة المكرمة من أهم مدن شبه الجزيرة العربية، حيث تقع في وادٍ تحيط به الجبال العالية، مما وفر لها حماية طبيعية وجعل الوصول إليها أمرًا صعبًا. وعلى الرغم من طبيعتها الجبلية وندرة المياه والزراعة فيها، إلا أن موقعها المميز جعلها مركزًا دينيًّا وتجاريًّا بارزًا في المنطقة."}]},{"title":"وفاة النبي ﷺ","src":[53],"blocks":[{"t":"flow","steps":[{"h":"السنة العاشرة من الهجرة","body":"أدى النبي ﷺ فريضة الحج، وألقى فيها خطبة الوداع، وأرسى فيها مبادئ الدين والحياة وحسن معاملة النساء."},{"h":"العام الحادي عشر","body":"بعد عودته إلى المدينة، أصيب بمرض شديد، وانتقل إلى جوار ربه بعد تمام رسالته ونشر نور الإسلام."}]},{"t":"fact","kind":"تعلمت","text":"لقد تعلمت أن الصبر والتخطيط هما البداية الحقيقية لأي نجاح، وأن التعاون والعدل هما الأساس في بناء مجتمع قوي."},{"t":"ask","kind":"ألاحظ وأجيب","q":["ما الدروس المستفادة من فتح مكة ٨ هـ؟","ما رأيك في هذه العبارة: يُعد صلح الحديبية خطوة مهمة نحو عالمية الدعوة؟","علام تدل وصية النبي ﷺ بحسن معاملة النساء؟"]}]},{"title":"تدريبات الدرس","src":[54,55],"ex":true,"blocks":[{"t":"read","h":"اقرأ وحلل: صحيفة المدينة","text":"تُعد صحيفة المدينة أول وثيقة سياسية في الإسلام، وأول نموذج عملي للتعايش بين الأديان والثقافات في مجتمع واحد. فقد ضمَّت المدينة آنذاك المسلمين واليهود وغيرهم، فوضع النبي ﷺ هذه الوثيقة لتضمن الحقوق والواجبات، وتمنع الفوضى والنزاع. ولم تفرِّق في الحماية أو الكرامة بين المسلمين وغير المسلمين، وهو مبدأ سبَّاق في إرساء مفهوم المواطنة، كما ضمنت حرية العقيدة، وألزمت الجميع بالدفاع المشترك عن المدينة، مما يجعلها نموذجًا يُحتذى به في بناء المجتمعات الحديثة."},{"t":"ask","kind":"اقرأ وحلل","q":["استخرج من الفقرة ما يدل على العدل والمساواة بين الناس.","دلل من الفقرة على أن الصحيفة نموذج يُحتذى به في بناء المجتمعات الحديثة.","قارن بين ما ورد في صحيفة المدينة من مبادئ، وبعض الوثائق الحديثة في العالم، من حيث حماية الحقوق واحترام العقائد."]},{"t":"ask","kind":"صمم ورتب","q":["رتِّب في خط زمني الأحداث التاريخية التالية من الأقدم إلى الأحدث: (غزوة بدر – وفاة النبي ﷺ – صلح الحُدَيْبية – غزوة الخندق – هجرة النبي ﷺ – حجة الوداع)."]},{"t":"ask","kind":"اختر الإجابة الصحيحة مما بين القوسين","q":["توفي النبي محمد ﷺ في …… (مكة – المدينة – الطائف – الرياض)","بدأت مرحلة عالمية الدعوة بعد …… (صلح الحديبية – غزوة أُحُد – غزوة الخندق – فتح مكة)","انتصر المسلمون دون قتال في غزوة …… (أُحُد – بدر – الخندق – الحُدَيْبية)","تحول نصر المسلمين إلى هزيمة في غزوة …… (بدر – أُحُد – الخندق – فتح مكة)","أول أعمال النبي ﷺ بعد الهجرة …… (المؤاخاة بين المهاجرين والأنصار – بناء المسجد – وضع صحيفة المدينة – تأمين الدولة)"]},{"t":"ask","kind":"اكتب (صواب) أو (خطأ)","q":["هاجر النبي ﷺ إلى المدينة سرًّا.","أحد أعمال النبي ﷺ في المدينة المؤاخاة بين المهاجرين والأنصار.","أحد أسباب انتصار المسلمين في غزوة بدر حفر الخندق.","حطَّم النبي ﷺ الأصنام عند فتح مكة وعفا عن أهلها."]},{"t":"ask","kind":"بم تفسر…؟","q":["توجُّه النبي ﷺ لفتح مكة.","أهمية المسجد في الإسلام.","أحد أسباب انتصار المسلمين في غزوة بدر تطبيق مبدأ الشورى.","أهمية صلح الحُدَيْبية."]},{"t":"ask","kind":"أيِّد بالأدلة صحة العبارات التالية","q":["تحلى النبي ﷺ بالأخلاق الحميدة في التعامل مع قريش.","نصر الله المسلمين في إحدى الغزوات دون قتال."]},{"t":"ask","kind":"ما المقصود بالمصطلحات التاريخية التالية…؟","q":["المهاجرون.","الأنصار."]},{"t":"ask","kind":"هيا نستعد للدرس القادم","q":["ماذا حدث بعد وفاة النبي ﷺ؟ ومن سيقود الأمة بعد النبي ﷺ؟"]}]}],"blocks":29,"hasEx":true},{"id":"u2l3","unit":2,"n":3,"title":"إنجازات الخلفاء الراشدين (رضي الله عنهم)","bookPages":[56,63],"icon":"scroll","objectives":["أتعرّف أهم إنجازات الخلفاء الراشدين رضي الله عنهم.","أصف سيرة كل خليفة قبل الإسلام وبعده باختصار.","أوضح أثر الخلفاء الراشدين رضي الله عنهم في نشر الإسلام وإدارة الدولة الإسلامية.","أستنتج أهم القيم التي التزم بها الخلفاء الراشدون رضي الله عنهم في حياتهم."],"panels":[{"title":"من هم الخلفاء الراشدون؟","src":[56],"blocks":[{"t":"intro","text":"أربعة خلفاء عظماء خلفوا الرسول ﷺ وساروا على نهجه ونشروا الإسلام وحققوا العدالة بين الناس، كل واحد منهم له مواقف عظيمة، وقرارات حكيمة، وأعمال لا تُنسى. هيا بنا نبدأ رحلتنا ونتعرَّف عليهم واحدًا تلو الآخر، لنتعلم منهم دروسًا في القيادة والعدل."},{"t":"note","text":"بعد وفاة النبي ﷺ، اجتمع الصحابة في سقيفة بني ساعدة للتشاور فيمن يتولى خلافة المسلمين، وتم مبايعة أبي بكر الصدِّيق رضي الله عنه ليصبح أول خليفة للمسلمين."},{"t":"ask","kind":"أتعلم وأكتشف","q":["من هم الخلفاء الراشدون؟ ولماذا تم اختيار أبي بكر الصدِّيق رضي الله عنه أول خليفة للمسلمين؟"]}]},{"title":"أبو بكر الصدِّيق رضي الله عنه (عبد الله بن أبي قحافة)","src":[57,58],"blocks":[{"t":"intro","text":"كان من كبار تجار مكة، معروفًا بين الناس بالصدق والأمانة. وكانت تربطه علاقة قوية بالنبي ﷺ، فلما دعاه إلى الإسلام استجاب فورًا دون تردُّد."},{"t":"chips","h":"خلافته: بعد وفاة النبي ﷺ أجمع المسلمون عليه؛ وذلك لعدة أسباب، منها","items":["أول مَن آمَن مِن الرجال.","أسلم على يديه عدد كبير من الصحابة.","أنفق أكثر أمواله في سبيل الله لمساعدة الفقراء والمساكين.","صَاحِب النبي ﷺ الذي شاركه في الهجرة.","شارك النبي ﷺ في جميع غزواته.","اختاره النبي ﷺ ليؤمَّ المسلمين في الصلاة أثناء مرضه."]},{"t":"cards","h":"أهم أعماله بعد تولِّيه الخلافة","items":[{"icon":"shield","h":"١- إرسال جيش أسامة بن زيد","body":"أرسل جيش أسامة بن زيد إلى بلاد الشام لتأمين حدود الدولة الإسلامية مع الروم."},{"icon":"flag","h":"٢- محاربة المرتدين","body":"قضى على حركات الرِّدَّة، ومنها القضاء على «مُسَيْلِمة الكذاب» الذي ادَّعى النبوة."},{"icon":"book","h":"٣- جمع القرآن الكريم","body":"كلَّف أبو بكر الصديق رضي الله عنه الصحابي زيد بن ثابت بجمع القرآن بعد استشهاد عدد كبير من حَفَظَتِه في حروب الردة."},{"icon":"globe","h":"٤- الفتوحات الإسلامية","body":"أرسل الجيوش لقتال الفرس والروم في الشام والعراق، لنشر الإسلام وتأمين حدود الدولة."}]},{"t":"terms","items":[{"term":"المرتدُّون","def":"جماعة من الناس خرجوا عن الإسلام، وادعى بعضهم النبوة."}]},{"t":"note","text":"وقبل وفاة أبي بكر رضي الله عنه رشَّح الصحابي عمر بن الخطاب رضي الله عنه ليكون الخليفة من بعده، ووافق الصحابة على ذلك."},{"t":"fact","kind":"قيم أتعلمها","text":"الشورى والتعاون يقودان إلى قرارات حكيمة ويحافظان على وحدة المجتمع."},{"t":"ask","kind":"أفكر وأجيب","q":["لماذا أنفق أبو بكر الصديق رضي الله عنه الكثير من ماله؟","وضح سبب جمع أبي بكر الصدِّيق رضي الله عنه للقرآن الكريم.","ماذا كان يحدث إذا لم يقم أبو بكر رضي الله عنه بمحاربة المرتدِّين؟"]}]},{"title":"عمر بن الخطاب رضي الله عنه","src":[58,59],"blocks":[{"t":"intro","text":"أسلم في السنة الخامسة من البعثة، لقَّبه النبي ﷺ بالفاروق لأنه فرَّق بين الحق والباطل، شارك مع النبي ﷺ في كل غزواته، وكان مثالًا في العدل والزهد والتواضع والرحمة."},{"t":"cards","h":"أهم أعماله بعد تولِّيه الخلافة","items":[{"icon":"scroll","h":"١- إنشاء الدواوين","body":"لتنظيم شئون الدولة، مثل ديوان بيت المال وديوان الجند."},{"icon":"calendar","h":"٢- التقويم الهجري","body":"جعل من هجرة النبي ﷺ بداية للتقويم الهجري للمسلمين."},{"icon":"city","h":"٣- تأسيس مدن جديدة في البلاد المفتوحة","body":"منها الكوفة في العراق، والفسطاط في مصر."},{"icon":"globe","h":"٤- الفتوحات الإسلامية","body":"استكمل عمر بن الخطاب الفتوحات التي بدأت في عهد أبي بكر الصدِّيق رضي الله عنه."}]},{"t":"timeline","cap":"أهم الفتوحات في عهد عمر بن الخطاب","items":[{"n":"١٣ هـ","h":"الشام","text":"على يد خالد بن الوليد في معركة اليرموك."},{"n":"١٥ هـ","h":"العراق","text":"على يد سعد بن أبي وقاص في معركة القادسية."},{"n":"٢١ هـ","h":"فارس","text":"على يد النعمان بن مُقَرِّن في معركة فتح الفتوح."},{"n":"٢١ هـ","h":"مصر","text":"فتحها عمرو بن العاص، وأمَّن الأقباط على أنفسهم وأموالهم وكنائسهم."}]},{"t":"note","text":"استشهد عمر بن الخطاب رضي الله عنه في صلاة الفجر على يد أبي لؤلؤة المجوسي سنة ٢٣ هـ."},{"t":"fact","kind":"هل تعلم؟","text":"رفض عمر بن الخطاب رضي الله عنه الصلاة داخل كنيسة القيامة عندما عرض عليه البطريرك ذلك؛ حتى لا يتخذها المسلمون مسجدًا من بعده، وصلى خارجها احترامًا لمكانتها ولأهلها."},{"t":"fact","kind":"قيم أتعلمها","text":"العدل أساس القوة، واحترام الناس يكون بالحق لا بالتمييز."},{"t":"ask","kind":"أفكر وأجيب","q":["فسِّر تلقيب عمر بن الخطاب رضي الله عنه بالفاروق.","حدِّد أهم أعمال عمر بن الخطاب رضي الله عنه بعد تولِّيه الخلافة موضحًا السبب."]}]},{"title":"عثمان بن عفان رضي الله عنه","src":[59],"blocks":[{"t":"intro","text":"أسلم على يد أبي بكر الصدِّيق رضي الله عنه، وشارك مع النبي ﷺ في جميع الغزوات ما عدا غزوة بدر بسبب مرض زوجته، وأنفَق كثيرًا من ماله في خدمة الإسلام."},{"t":"cards","h":"أهم أعماله بعد تولِّيه الخلافة","items":[{"icon":"book","h":"١- نسخ القرآن الكريم في مصحف واحد","body":"وتوزيعه على البلدان المفتوحة لتوحيد قراءة القرآن الكريم."},{"icon":"ship","h":"٢- إنشاء أول أسطول بحري إسلامي","body":"لحماية سواحل مصر والشام من هجمات الروم في عهده."},{"icon":"globe","h":"٣- الفتوحات الإسلامية","body":"لتأمين حدود الدولة ونشر الإسلام."}]},{"t":"note","text":"أدت الفتنة التي أثارها عبد الله بن سبأ إلى استشهاد الخليفة عثمان بن عفان رضي الله عنه عام ٣٥ هـ."},{"t":"fact","kind":"قيم أتعلمها","text":"التضحية والعطاء يعبِّران عن حب الوطن."},{"t":"ask","kind":"أفكر وأستنتج","q":["ما سبب إنشاء الأسطول البحري الإسلامي في عهد عثمان بن عفان رضي الله عنه؟","بم تفسر عدم مشاركة عثمان بن عفان رضي الله عنه في غزوة بدر ٢ هـ؟"]}]},{"title":"علي بن أبي طالب رضي الله عنه","src":[60],"blocks":[{"t":"intro","text":"تربى في بيت النبي ﷺ وكان معروفًا بذكائه وفصاحته وبلاغته، كما اتَّصف بالعلم والزهد والتواضع. أسلم وهو في العاشرة من عمره، وتعلَّم في دار الأرقم بن أبي الأرقم، ويُعد أول فدائي في الإسلام؛ لأنه نام في فِراش النبي ﷺ ليلة الهجرة. شارك مع النبي ﷺ في كل الغزوات ما عدا غزوة تبوك."},{"t":"cards","h":"أهم أعماله بعد تولِّيه الخلافة","items":[{"icon":"city","h":"١- نقل مقر الخلافة","body":"من المدينة إلى الكوفة في العراق لتسهيل إدارة شئون الدولة بعد اتساعها."},{"icon":"shield","h":"٢- تنظيم الشرطة","body":"لحفظ الأمن والاستقرار وملاحقة المجرمين والخارجين عن القانون."}]},{"t":"note","text":"استشهد علي بن أبي طالب رضي الله عنه عام ٤٠ هـ على يد عبد الرحمن بن مُلْجَم أثناء خروجه لصلاة الفجر."},{"t":"fact","kind":"معلومة إثرائية","text":"حرَص علي بن أبي طالب رضي الله عنه على تطبيق العدل، فخصص يومًا للنظر في مظالم الناس."},{"t":"fact","kind":"قيم أتعلمها","text":"التواضع مع الناس من صفات القادة الحقيقيين."},{"t":"fact","kind":"تعلمت","text":"تعلمت من هذا الدرس الصدق والأمانة، وأن العدل أساس كل شيء."},{"t":"ask","kind":"أقرأ وأحدد","q":["اذكر أهمية الشرطة في خلافة علي بن أبي طالب رضي الله عنه.","لماذا أُطلِق على علي بن أبي طالب رضي الله عنه أول فدائي في الإسلام؟"]}]},{"title":"تدريبات الدرس","src":[61,62,63],"ex":true,"blocks":[{"t":"read","h":"اقرأ وحلل: خطاب الخليفة أبي بكر الصدِّيق رضي الله عنه بعد مبايعته خليفة للمسلمين","text":"«أما بعد أيها الناس، فإني وُلِّيت عليكم ولست بخيركم، فإن أحسنت فأعينوني، وإن أسأت فقوِّموني، الصدق أمانة، والكذب خيانة، والضعيف فيكم قوي عندي حتى أُرِيحَ (أَرُدَّ) عليه حقه إن شاء الله تعالى، والقوي فيكم ضعيف عندي حتى آخُذ منه الحق إن شاء الله تعالى»."},{"t":"ask","kind":"اقرأ وحلل","q":["حدد من الخطاب أعلاه القواعد التي استند إليها الخليفة أبو بكر الصدِّيق رضي الله عنه في إدارة شئون الدولة الإسلامية.","حدد أهم الصفات الواجب توافرها في الحاكم."]},{"t":"ask","kind":"صمم ورتب","q":["رتِّب الخلفاء الراشدين أدناه على خط زمني من تصميمك: (عمر بن الخطاب – عثمان بن عفان – أبو بكر الصدِّيق – علي بن أبي طالب)."]},{"t":"read","h":"اقرأ وحلل: عمر بن الخطاب رضي الله عنه وفتح بيت المقدس","text":"عندما فُتح بيت المقدس في عهد الخليفة عمر بن الخطاب رضي الله عنه، طلب أهل المدينة أن يسلموا مفاتيح المدينة للخليفة بنفسه، فخرج من المدينة إلى بيت المقدس ومعه خادمه وجمل واحد. كان عمر وخادمه يتبادلان الركوب، فإذا ركب أحدهما مشى الآخر، وعندما اقتربا من بيت المقدس، كان الدور على عمر أن يمشي، فرفض أن يركب ليظهر بمظهر القائد، وقال: «نحن قوم أعزَّنا الله بالإسلام، فإن ابتغينا العزة بغيره أذلَّنا الله». دخل عمر إلى بيت المقدس بثوب بسيط والغبار على ملابسه، مما أثار إعجاب الناس بتواضعه وعدله."},{"t":"ask","kind":"اقرأ وحلل","q":["صف مظاهر تواضع وعدل عمر بن الخطاب رضي الله عنه كما ظهرت في رحلته إلى بيت المقدس."]},{"t":"ask","kind":"اختر الإجابة الصحيحة مما بين القوسين","q":["الخليفة الذي قام بمحاربة المرتدِّين …… (أبو بكر الصدِّيق – عمر بن الخطاب – عثمان بن عفان – علي بن أبي طالب)","قام بتنظيم الشرطة الخليفة …… (أبو بكر الصدِّيق – عمر بن الخطاب – عثمان بن عفان – علي بن أبي طالب)","قام بوضع التقويم الهجري للدولة الإسلامية الخليفة …… (أبو بكر الصدِّيق – عمر بن الخطاب – عثمان بن عفان – علي بن أبي طالب)","أول الخلفاء الراشدين رضي الله عنهم هو …… (أبو بكر الصدِّيق – عمر بن الخطاب – عثمان بن عفان – علي بن أبي طالب)","تم نسخ القرآن الكريم في عهد …… رضي الله عنه (أبي بكر الصدِّيق – عمر بن الخطاب – عثمان بن عفان – معاوية بن أبي سفيان)"]},{"t":"ask","kind":"اكتب (صواب) أو (خطأ)","q":["قام أسامة بن زيد بجمع القرآن بتكليف من الخليفة أبي بكر الصدِّيق رضي الله عنه.","يرجع بدء الفتوحات الإسلامية لعهد الخليفة أبي بكر الصدِّيق رضي الله عنه.","يرجع تأسيس المدن في الدولة الإسلامية لعهد الخليفة عمر بن الخطاب رضي الله عنه.","أنشأ الخليفة عمر بن الخطاب رضي الله عنه أول أسطول بحري إسلامي.","الخليفة علي بن أبي طالب رضي الله عنه هو أول من نظَّم الشرطة.","يُعد عمر بن الخطاب أول من جمع القرآن الكريم.","الفتوحات الإسلامية توقفت في عهد الخلفاء الراشدين."]},{"t":"ask","kind":"بم تفسر…؟","q":["اختيار أبي بكر الصدِّيق رضي الله عنه أول خليفة للمسلمين.","قيام الخليفة عثمان بن عفان رضي الله عنه بنسخ القرآن في مصحف واحد."]},{"t":"ask","kind":"دلل على صحة العبارات التالية","q":["اتسعت حركة الفتوحات الإسلامية في خلافة عمر بن الخطاب رضي الله عنه.","حرص الخليفة علي بن أبي طالب رضي الله عنه على حفظ الأمن داخل الدولة الإسلامية."]},{"t":"ask","kind":"ما النتائج المترتبة على…؟","q":["إرسال جيش أسامة بن زيد إلى بلاد الشام؟"]},{"t":"ask","kind":"اكتب ما تشير إليه كل عبارة مما يلي","q":["أحد الخلفاء الراشدين الذي قام بجمع القرآن الكريم.","اهتم ببناء المدن في البلاد المفتوحة.","أحد الخلفاء الراشدين رضي الله عنهم الذي نقل العاصمة من المدينة إلى الكوفة.","شارك النبي ﷺ في كل الغزوات ما عدا غزوة بدر."]},{"t":"ask","kind":"هيا نستعد للدرس القادم","q":["حدد اسم الدولتين اللتين جاءتا بعد عصر الخلفاء الراشدين رضي الله عنهم."]}]}],"blocks":41,"hasEx":true},{"id":"u2l4","unit":2,"n":4,"title":"الدولة الإسلامية (الأمويون – العباسيون)","bookPages":[64,70],"icon":"dome","objectives":["أشرح دور بعض الخلفاء الأمويين والعباسيين في ازدهار الحضارة الإسلامية.","أتعرّف ملامح النهضة العمرانية في العصرين الأموي والعباسي.","أفسّر أسباب ازدهار الحضارة الإسلامية في العصرين الأموي والعباسي.","أستنتج أسباب سقوط الدولتين الأموية والعباسية.","أوضح كيف انتقلت الخلافة من الأمويين إلى العباسيين.","أُعبر عن تقديري لدور الخلفاء في خدمة الإسلام وازدهار العلوم."],"panels":[{"title":"عهد جديد للدولة الإسلامية","src":[64],"blocks":[{"t":"intro","text":"بعد انتهاء عصر الخلفاء الراشدين، بدأت الدولة الإسلامية عهدًا جديدًا، اتسعت فيه الفتوحات، وتطور نظام الحكم والإدارة، وازدهرت العلوم والعمارة في مختلف المجالات."},{"t":"stats","items":[{"v":"٤١ – ١٣٢","u":"هـ","l":"عصر الدولة الأموية","d":"قامت الدولة الأموية بعد انتهاء عصر الخلفاء الراشدين، وامتد حكمها حوالي ٩١ عامًا."},{"v":"١٣٢ – ٦٥٦","u":"هـ","l":"عصر الدولة العباسية","d":"قامت الدولة العباسية بعد هزيمة الأمويين في معركة الزاب الكبرى عام ١٣٢ هـ."}]},{"t":"ask","kind":"أتعلم وأكتشف","q":["هل تعرف من تولَّى حكم الدولة الإسلامية بعد استشهاد الخليفة علي بن أبي طالب رضي الله عنه؟ وما أهم إنجازات من جاء بعده؟"]}]},{"title":"عصر الدولة الأموية (٤١ – ١٣٢) هـ","src":[65,66],"blocks":[{"t":"people","items":[{"name":"معاوية بن أبي سفيان","when":"٤١ – ٦٠ هـ","tag":"أول خلفاء الدولة الأموية.","works":["اتخذ من دمشق عاصمة للأمويين.","اهتم بالبحرية الإسلامية.","أنشأ مدينة القيروان لنشر الإسلام في شمال إفريقيا.","أسَّس ديوان الخاتم لحماية رسائل الدولة من التزوير."]},{"name":"عبد الملك بن مروان","when":"٦٥ – ٨٦ هـ","tag":"في عهده استقرت الدولة الإسلامية بعد فترة من الفوضى والصراعات.","works":["قام بسك أول عملة إسلامية.","أمر بنَقْط المصحف لتسهيل قراءة القرآن الكريم.","شيَّد مسجد قبة الصخرة في فلسطين.","عرَّب الدواوين للغة العربية."]},{"name":"الوليد بن عبد الملك","when":"٨٦ – ٩٦ هـ","tag":"تميَّز عهده بالرخاء الاقتصادي، وانتشار الأمن والاستقرار.","works":["واصل الفتوحات الإسلامية شرقًا إلى بلاد السند، وغربًا إلى بلاد الأندلس، وبلغَت الدولة الأموية أقصى اتساعها.","أعاد بناء المسجد النبوي ووسع الحرم المكي.","شيَّد المسجد الأموي في دمشق."]},{"name":"عمر بن عبد العزيز","when":"٩٩ – ١٠١ هـ","tag":"أُطلِق عليه «خامس الخلفاء الراشدين»؛ لما عُرف عنه من عدل وزهد وحرص على مصلحة الأمة.","works":["اختار القضاة والولاة والموظفين ممن عُرِفوا بحُسن السيرة والعدل.","نشر الإسلام في البلاد المفتوحة بالقدوة والموعظة الحسنة.","اهتم بالعلم والعلماء، وشيَّد المدارس."]}]},{"t":"fact","kind":"معلومة إثرائية","text":"في خلافة عمر بن عبد العزيز لم يكن هناك فقراء أو محتاجون، حتى إن عُمَّال الزكاة لم يجدوا من يعطوه الزكاة!"},{"t":"ask","kind":"أفكر وأستنتج","q":["ما النتائج المترتبة على نَقْط المصحف الشريف في عهد عبد الملك بن مروان؟","لماذا يُعد عمر بن عبد العزيز قدوة في الحكم؟"]},{"t":"ask","kind":"أفكر وأقارن","q":["قارن بين جهود معاوية بن أبي سفيان والوليد بن عبد الملك في العمارة الإسلامية."]}]},{"title":"أسباب ضعف وسقوط الدولة الأموية","src":[66],"blocks":[{"t":"chips","h":"الأسباب","items":["تولى أواخر عهد الدولة الأموية خلفاء ضعفاء مما كان سببًا في سقوط الدولة.","كثرة الصراعات بين القبائل العربية بسبب التنافس على السلطة.","ظهور الدعوة العباسية على يد أبي مسلم الخراساني."]},{"t":"note","text":"قامت الدولة العباسية بعد هزيمة الأمويين في معركة الزاب الكبرى عام ١٣٢ هـ."},{"t":"fact","kind":"قيم أتعلمها","text":"أساس قوة الأمم وبقائها يكمن في وحدتها وتماسك صفوفها، أما الصراع والانقسام فهما أول طريق الضعف والسقوط والانهيار."},{"t":"fact","kind":"حقائق جغرافية","text":"إقليم خراسان، الذي انطلقت منه الدعوة العباسية، يقع اليوم بين عدة دول هي: إيران، وأفغانستان، وتركمانستان، وأوزبكستان."},{"t":"ask","kind":"ألاحظ وأحلل","q":["ما السبب الأهم في سقوط الدولة الأموية؟"]}]},{"title":"عصر الدولة العباسية (١٣٢ – ٦٥٦) هـ","src":[66,67,68],"blocks":[{"t":"duo","a":{"h":"العصر العباسي الأول","items":["يُعرف بـ«العصر الذهبي».","يتميز بقوة الخلفاء وازدهار العلوم والثقافة."]},"b":{"h":"العصر العباسي الثاني","items":["هو عصر الضعف والانقسام."]}},{"t":"people","h":"أبرز خلفاء العصر العباسي الأول وإنجازاتهم","items":[{"name":"أبو العباس عبد الله","when":"١٣٢ – ١٣٦ هـ","works":["وضع أسس الدولة الجديدة.","نقل عاصمة الخلافة إلى مدينة الأنبار في العراق.","اهتم براحة الحُجاج، فجدَّد الطريق بين مكة والكوفة، وزوَّده بالمنارات لإرشاد المسافرين."]},{"name":"أبو جعفر المنصور","when":"١٣٦ – ١٥٨ هـ","tag":"المؤسِّس الحقيقي للدولة العباسية.","works":["قضى على الثورات والفتن، ونشر الأمن والاستقرار في أرجاء الدولة.","بَنى مدينة بغداد، وجعلها عاصمة الخلافة."]},{"name":"هارون الرشيد","when":"١٧٠ – ١٩٣ هـ","tag":"أشهر خلفاء الدولة العباسية.","works":["اشتهر بحبه للعلم والعلماء.","أسس مكتبة «بيت الحكمة» في بغداد.","أقام علاقات قوية مع ملوك أوروبا.","أنشأ سوق الورَّاقين في بغداد لنسخ الكتب وبيعها.","توسعت الدولة الإسلامية في عهده."]},{"name":"المأمون بن هارون","when":"١٩٨ – ٢١٨ هـ","tag":"اهتم بالعلوم والفلك.","works":["شجع على ترجمة الكتب من الحضارات الأخرى.","دعم العلماء والمفكرين في مختلف العلوم.","أنشأ أول مرصد فلكي في بغداد لرصد النجوم."]},{"name":"المعتصم بالله","when":"٢١٨ – ٢٢٧ هـ","works":["اهتم ببناء جيش قوي، وضم إليه الجنود الأتراك.","أنشأ مدينة سامراء لتكون مَقرًّا للخلافة.","نجح في فتح مدينة عمورية."]}]},{"t":"fact","kind":"معلومة إثرائية","text":"سوق الوراقين في بغداد مخصص لبيع الكتب ونسخها، وكان هذا السوق مليئًا بالعلماء والطلاب والمهتمين بالعلم."},{"t":"ask","kind":"أفهم وأحلل","q":["ما أهمية دور أبي العباس في قيام الدولة العباسية؟","لماذا يُعد أبو جعفر المنصور المؤسِّس الحقيقي للدولة العباسية؟"]},{"t":"ask","kind":"أفكر وأجيب","q":["اكتب رأيك في أحد خلفاء الدولة العباسية واعرضه على معلمك.","فسِّر: يُعد عهد هارون الرشيد من أزهى عصور الدولة العباسية.","لماذا يُعد المأمون من أكثر المهتمين بالعلم؟"]}]},{"title":"أسباب سقوط الدولة العباسية","src":[68],"blocks":[{"t":"chips","h":"الأسباب","items":["الصراع بين الأمراء العباسيين على الحكم.","ضعف الخلفاء العباسيين في نهاية العصر العباسي الثاني.","سيطرة العناصر غير العربية على نظم الحكم."]},{"t":"note","text":"كل ذلك أدى في النهاية إلى سقوط الدولة العباسية على يد المغول سنة ٦٥٦ هـ، بعد أن استمرت أكثر من خمسة قرون."},{"t":"fact","kind":"تعلمت","text":"تعلمت من الدرس أن الدولتين الأموية والعباسية اهتمتا بالعلم ونشر الإسلام، وأن التقدم يأتي من خلال العدل والاجتهاد."},{"t":"ask","kind":"أفكر وأستنتج","q":["ما النتائج المترتبة على ضعف حكام الدولة العباسية؟"]}]},{"title":"تدريبات الدرس","src":[69,70],"ex":true,"blocks":[{"t":"read","h":"اقرأ وحلل: الدولة العباسية","text":"تُعد الدولة العباسية من أعظم الدول الإسلامية، وقد تأسست عام ١٣٢هـ (٧٥٠م) على يد أبي العباس عبد الله بعد سقوط الدولة الأموية. اتخذت في البداية الأنبار عاصمة لها، ثم انتقل العباسيون بعاصمتهم إلى بغداد التي أصبحت مركزًا للعلم والثقافة والاقتصاد.\nتميَّزت الدولة العباسية بازدهار العلوم والفنون، وشهدت العصر الذهبي للحضارة الإسلامية، حيث ظهرت شخصيات بارزة مثل الخوارزمي رائد الرياضيات ومؤسس علم الخوارزميات، وابن سينا في الطب، والرازي في الكيمياء. كما ازدهرت حركة الترجمة من اللغات اليونانية والفارسية إلى العربية."},{"t":"ask","kind":"اقرأ وحلل","q":["من مؤسِّس الدولة العباسية؟","ما العاصمة التي بناها الخليفة أبو جعفر المنصور؟","ما اسم المؤسسة العلمية التي أنشأها الخليفة المأمون؟","اذكر اثنين من العلماء الذين ظهروا في العصر العباسي."]},{"t":"ask","kind":"أفهم وأجيب (نشاط كتابي)","q":["اكتب فقرة قصيرة تشرح فيها سبب ازدهار الدولة العباسية في الجانب العلمي والثقافي."]},{"t":"ask","kind":"ألاحظ وأجيب: لاحظ صورة المسجد الأموي بدمشق (بالكتاب صفحة ٦٩)، ثم أجب","q":["من قام بإنشاء المسجد الأموي بدمشق؟","استخدم شبكة المعلومات الدولية (الإنترنت) لتتعرف على أدوار المساجد في الدولة الإسلامية.","تخيَّل أنك صحفي تعيش في زمن الخليفة عمر بن عبد العزيز، وطُلب منك أن تُجري معه لقاء صحفيًّا، اطرح ثلاثة أسئلة بناء على ما تعرفه من أعماله."]},{"t":"ask","kind":"اكتب (صواب) أو (خطأ)","q":["كان لدعم أبي مسلم الخراساني دور في نجاح قيام الدولة العباسية.","قام الخليفة العباسي هارون الرشيد بإنشاء سوق الوراقين.","استمرت الدولة العباسية أكثر من ستة قرون.","ازدهرت حركة الترجمة في العصر العباسي الثاني."]},{"t":"ask","kind":"اختر الإجابة الصحيحة مما بين القوسين","q":["قام الخليفة …… ببناء مدينة سامراء. (أبو العباس – المأمون – المعتصم – الأمين)","الخليفة الذي قام ببناء مدينة بغداد …… (أبو جعفر المنصور – الوليد بن عبد الملك – أبو مسلم الخراساني – مروان بن محمد)","عاصمة الدولة الإسلامية في العصر الأموي …… (المدينة – دمشق – الكوفة – بغداد)","كل الأعمال التالية قام بها الوليد بن عبد الملك، ما عدا …… (بناء المسجد الأموي – الاهتمام بالفتوحات الإسلامية – بناء مسجد قبة الصخرة – توسعة الحرم النبوي)","قام بتعريب الدواوين في الدولة الإسلامية …… (معاوية بن أبي سفيان – الوليد بن عبد الملك – عبد الملك بن مروان – عمر بن عبد العزيز)"]},{"t":"ask","kind":"بم تفسر…؟","q":["نجاح العباسيين في إسقاط الدولة الأموية.","ضعف الدولة الأموية في أواخر عهدها.","سقوط الدولة العباسية."]},{"t":"ask","kind":"دلل على صحة العبارة التالية","q":["شهد المجتمع الإسلامي في العصر الأموي نهضة عمرانية."]},{"t":"ask","kind":"هيا نستعد للدرس القادم","q":["ما العوامل التي تساعد على قيام الزراعة؟"]}]}],"blocks":30,"hasEx":true},{"id":"u3l1","unit":3,"n":1,"title":"النشاط الزراعي في وطننا العربي","bookPages":[76,83],"icon":"wheat","objectives":["أصنف عوامل قيام الزراعة في الوطن العربي.","أقرأ خريطة المناطق الزراعية في الوطن العربي.","أتعرّف أهم المحاصيل الزراعية في الوطن العربي.","أقدّم نماذج لمشكلات الزراعة في الوطن العربي.","أفسّر أهمية النشاط الزراعي في الوطن العربي."],"panels":[{"title":"مقومات الزراعة في الوطن العربي","src":[76],"blocks":[{"t":"intro","text":"يمتلك الوطن العربي العديد من الثروات، منها الثروة الحيوانية والسمكية، والمعادن ومصادر الطاقة. كما تتنوع به الأنشطة الاقتصادية مثل النشاط الزراعي والسياحي والصناعي والتجاري. وسوف نبدأ بالنشاط الزراعي حيث يمتلك الوطن العربي منذ القِدَم كل مقومات الزراعة الأساسية، مما جعله موطنًا للاستقرار البشري، ومَهْدًا لقيام حضارات مزدهرة عبر العصور."},{"t":"duo","a":{"h":"١- المقومات الطبيعية","items":["التربة الخصبة","تنوع المناخ","المياه العذبة"]},"b":{"h":"٢- المقومات البشرية","items":["الأيدي العاملة","رأس المال","السوق","وسائل النقل"]}},{"t":"ask","kind":"أتأمل وأكتشف","q":["هل تَرى أن الوطن العربي امتلك ما جعله مَهْدًا للحضارات القديمة؟ ولماذا؟"]}]},{"title":"المقومات الطبيعية للزراعة","src":[77],"blocks":[{"t":"map","img":"assets/b-u3-agri.jpg","cap":"خريطة (١) المناطق الزراعية في الوطن العربي — زراعة على المطر، زراعة على المياه الجوفية، زراعة على الري من الأنهار"},{"t":"ask","kind":"ألاحظ وأحلل","q":["لاحظ الخريطة وحدد مناطق الزراعة بالوطن العربي.","توقع أهم عامل مسئول عن قيام الزراعة في الوطن العربي."]},{"t":"cards","items":[{"icon":"soil","h":"١- التربة الخصبة","body":"تتوافر في سهول نهر النيل في مصر والسودان، وسهول دجلة والفرات في العراق.","more":"وهي تربة غنية تساعد على نمو المحاصيل."},{"icon":"sun","h":"٢- تنوع المناخ","body":"يتمتع الوطن العربي بمناخ معتدل ومطير في الشمال وحار ومطير في الجنوب.","more":"فترتب على ذلك تنوع المحاصيل الزراعية."},{"icon":"drop","h":"٣- المياه العذبة","body":"مثل نهر النيل في مصر والسودان، ونهرَي دجلة والفرات في العراق.","more":"والأمطار في بلاد المغرب ولبنان، والمياه الجوفية في الواحات."}]}]},{"title":"المقومات البشرية للزراعة","src":[78],"blocks":[{"t":"cards","items":[{"icon":"hands","h":"١- الأيدي العاملة المدربة","body":"الوطن العربي يمتلك ثروة بشرية مدربة على الزراعة، ويعرف كيفية استخدام الأساليب الحديثة."},{"icon":"coin","h":"٢- رأس المال","body":"ضروري لإنشاء المشروعات الزراعية وشراء البذور والأسمدة والآلات.","more":"وتُعد دول الخليج من أكثر الدول امتلاكًا لرأس المال."},{"icon":"market","h":"٣- الأسواق","body":"مهمة لبيع وتسويق المنتجات الزراعية.","more":"حيث يترتب على بيع المنتجات زيادة الإنتاج الزراعي ومنافسة الدول الأخرى."},{"icon":"truck","h":"٤- وسائل النقل والمواصلات","body":"تساعد على نقل المحاصيل من المَزارع إلى الأسواق قبل أن تتلف."}]},{"t":"note","text":"إذًا الأيدي العاملة ورأس المال والأسواق ووسائل النقل، كلها ضرورية لنجاح الزراعة. فالعوامل البشرية تكمل العوامل الطبيعية، وبهما معًا تحقِّق الزراعة نجاحًا كبيرًا في وطننا العربي."},{"t":"ask","kind":"أفكر وأجيب","q":["المقوم الأكثر أهمية للزراعة بوطننا العربي: وفرة المياه أم النقل والمواصلات؟","فسِّر نجاح الزراعة في بعض الدول العربية التي لا تمتلك أنهارًا."]}]},{"title":"أهم المحاصيل الزراعية في الوطن العربي","src":[79],"blocks":[{"t":"intro","text":"ينتج الوطن العربي أنواعًا متعددة من المحاصيل الزراعية، تُستخدم في الغذاء والصناعة والتجارة، ومن أهمها:"},{"t":"cards","items":[{"icon":"wheat","h":"١- الحبوب الغذائية: القمح","body":"تُعد مصر من أكثر الدول العربية إنتاجًا له، ويُستخدم في صناعة الخبز."},{"icon":"cane","h":"٢- المحاصيل السكرية: قصب السكر","body":"يُزرع في مناطق متعددة من صعيد مصر، ويُستخدم بشكل رئيسي في صناعة السكر."},{"icon":"cotton","h":"٣- محاصيل الألياف: القطن","body":"تتصدر مصر إنتاج القطن طويل التيلة، وهو من أجود الأنواع، ويُستخدم في صناعة الملابس والمنسوجات الفاخرة."}]},{"t":"ask","kind":"أناقش وأجيب","q":["اكتب فقرة عن أهم المحاصيل الزراعية في الوطن العربي."]}]},{"title":"أهمية الزراعة ومشكلاتها وحلولها","src":[80],"blocks":[{"t":"chips","h":"أهمية الزراعة: تُعد من أهم الأنشطة الاقتصادية في وطننا العربي؛ حيث تلعب دورًا كبيرًا في حياة السكان، فهي","items":["توفر الغذاء للإنسان، والعلف للحيوان.","توفر المواد الخام اللازمة للصناعة.","توفر فرص عمل للشباب.","مصدر رئيسي للدخل القومي لبعض الدول العربية."]},{"t":"fact","kind":"حقائق تاريخية","text":"سجل المصريون أنشطتهم الزراعية على جدران المعابد والمقابر، مما يدل على أهمية الزراعة في حياتهم واقتصادهم."},{"t":"ask","kind":"أتعلم وأطبق","q":["ماذا يمكن أن يحدث إذا لم تهتم الدول العربية بالزراعة؟"]},{"t":"duo","a":{"h":"أهم المشكلات التي تواجه الزراعة","items":["قلة الأمطار.","ندرة المياه العذبة.","التغيرات المناخية.","نقص العمالة المدربة.","التلوث والزحف العمراني.","ضعف الاستثمار الزراعي."]},"b":{"h":"جهود بعض الدول العربية لحل مشكلات الزراعة","items":["تحلية مياه البحر.","استصلاح الأراضي الصحراوية.","معالجة مياه الصرف.","بناء السدود والخزانات.","استخدام أساليب الري الحديثة مثل الرش والتنقيط.","استحداث بذور مقاومة للتغيرات المناخية."]}}]},{"title":"أهم المشروعات القومية لحل مشكلات الزراعة في مصر","src":[81],"blocks":[{"t":"cards","items":[{"icon":"sprout","h":"مشروع مستقبل مصر للزراعة المستدامة","body":"هو جزء من مشروع الدلتا الجديدة، ويهدف لاستصلاح أكثر من مليون فدان باستخدام طرق الري الحديثة والطاقة النظيفة.","more":"ويساعد في تحقيق الأمن الغذائي وتوفير فرص عمل للشباب."},{"icon":"palm","h":"مشروع توشكى بجنوب الوادي","body":"يهدف لاستصلاح آلاف الأفدنة بالصحراء الغربية، ويعتمد على مياه نهر النيل.","more":"ويزرع القمح والفواكه والنخيل، ويسهم في زيادة الرقعة الزراعية وتحقيق الأمن الغذائي."}]},{"t":"map","img":"assets/b-u3-toshka.jpg","cap":"خريطة مشروع التنمية الزراعية في توشكى جنوب مصر"},{"t":"ask","kind":"ألاحظ وأجيب","q":["استنتج من الخريطة مصدر المياه الذي يعتمد عليه مشروع توشكى الزراعي."]},{"t":"ask","kind":"أبحث وأجيب","q":["بالاستعانة بمصادر المعرفة المختلفة ابحث عن بعض المشروعات الزراعية الرائدة في الدول العربية واكتب ملخصًا عنها."]}]},{"title":"تدريبات الدرس","src":[82,83],"ex":true,"blocks":[{"t":"read","h":"اقرأ وحلل: الزراعة في وطننا العربي.. تحديات وحلول (نص إثرائي)","text":"الزراعة من أقدم الأنشطة التي مارسها الإنسان في الوطن العربي، وساعدت على قيام حضارات قديمة على ضفاف الأنهار. اليوم ما زالت الزراعة تلعب دورًا مهمًّا في توفير الغذاء وفرص العمل، ولكن تواجه الزراعة بعض التحديات مثل قلة المياه والتصحر؛ لذلك تعمل بعض الدول على إيجاد حلول مثل استصلاح الأراضي الصحراوية واستخدام أساليب الري الحديثة."},{"t":"ask","kind":"اقرأ وحلل","q":["ما العلاقة بين الزراعة وقيام الحضارات القديمة؟","اذكر اثنتين من فوائد الزراعة في الوقت الحاضر.","ما المشكلة التي تواجه الزراعة وذُكرت في النص؟","ما الحل الذي لجأت إليه الدول العربية لمواجهة هذه المشكلة؟","اقترح حلًّا لتطوير الزراعة في مصر."]},{"t":"ask","kind":"فكر وتوقع","q":["تخيَّل أنك خبير زراعي يعمل في دولة عربية، ومطلوب منك إعداد تقرير بسيط عن الزراعة في هذه الدولة: حدِّد ثلاثة مقومات (طبيعية أو بشرية) ساعدت على قيام الزراعة."]},{"t":"ask","kind":"اكتب (صواب) أو (خطأ)","q":["تُعد الزراعة من الأنشطة الاقتصادية المهمة في وطننا العربي.","قصب السكر من المحاصيل السكرية التي تُزرع في صعيد مصر.","من أهداف مشروع توشكى استصلاح الأراضي الصحراوية.","تنوع المناخ في وطننا العربي ساعد على زراعة محاصيل متنوعة.","استحداث أنواع جديدة من البذور يضر بالمُزارعين."]},{"t":"ask","kind":"أكمل العبارات التالية بكلمات مناسبة","q":["أحد المحاصيل السكرية التي تُزرع في الوطن العربي ……","أحد المقومات البشرية للزراعة ……","أحد مشكلات الزراعة في الوطن العربي ……","أحد المشروعات القومية الزراعية في مصر مشروع ……","تُستخدم محاصيل الألياف مثل القطن في ……"]},{"t":"ask","kind":"بم تفسر…؟","q":["أهمية الزراعة في الوطن العربي.","استخدام بعض الدول العربية أساليب ري حديثة."]},{"t":"ask","kind":"ما النتائج المترتبة على…؟","q":["تنوع المناخ في الوطن العربي؟"]},{"t":"ask","kind":"دلل على صحة العبارات الآتية","q":["تبذل مصر جهودًا كبيرة لحل مشكلات الزراعة.","الزراعة تُعد نشاطًا اقتصاديًّا مهمًّا في وطننا العربي."]},{"t":"ask","kind":"ما العلاقة بين…؟","q":["رأس المال والمشروعات الزراعية.","الزراعة والأمن الغذائي في وطننا العربي."]},{"t":"ask","kind":"هيا نستعد للدرس القادم","q":["الثروة الحيوانية مصدر مهم للغذاء والصناعة. هل يمكنك أن تتخيل حياتنا بدونها؟"]}]}],"blocks":30,"hasEx":true},{"id":"u3l2","unit":3,"n":2,"title":"الثروة الحيوانية والسمكية في وطننا العربي","bookPages":[84,91],"icon":"cow","objectives":["أحدّد المناطق التي تنتشر فيها المراعي الطبيعية في الوطن العربي.","أفسّر أهمية الثروة الحيوانية والسمكية في حياة سكان الوطن العربي.","ألخص المشكلات التي تتعرض لها الثروة الحيوانية والسمكية.","أقترح حلولًا للتحديات التي تواجه الثروة الحيوانية والسمكية في الوطن العربي."],"panels":[{"title":"المراعي الطبيعية في الوطن العربي","src":[84,85],"blocks":[{"t":"intro","text":"يتميز الوطن العربي بتربية أعداد كبيرة من الحيوانات، خاصة في المناطق التي تنتشر فيها المراعي الطبيعية، وتُعد هذه الثروة مصدرًا مهمًّا للغذاء، وتسهم في دعم الاقتصاد المحلي."},{"t":"terms","items":[{"term":"المراعي الطبيعية","def":"حشائش تنمو طبيعيًّا دون تدخل من الإنسان."}]},{"t":"note","text":"الحيوانات لا تُربى فقط في الحظائر، بل تربى أيضًا في المراعي الطبيعية التي خلقها الله، وتنقسم إلى:"},{"t":"duo","a":{"h":"١- المراعي المعتدلة (الإستبس)","items":["الأعشاب القصيرة.","تُربى عليها الأغنام والماعز.","كما في المغرب."]},"b":{"h":"٢- المراعي الحارة (السافانا)","items":["الحشائش الطويلة.","تُربى عليها الأبقار والأغنام.","كما في السودان."]}},{"t":"ask","kind":"أتأمل وأكتشف","q":["إذا كانت هناك مَراعٍ طبيعية واسعة في دولة عربية، فماذا تتوقع أن ينتشر فيها؟ ولماذا تُعد هذه المراعي مهمة للثروة الحيوانية؟"]},{"t":"ask","kind":"أحدد وأصنف","q":["صنِّف الآتي حسب ما ينتمي إلى: مَراعٍ معتدلة (الإستبس) – مَراعٍ حارة (السافانا): (الأغنام – الأبقار – الأعشاب القصيرة – الحشائش الطويلة – المَاعز – السودان – المغرب)."]}]},{"title":"الثروة الحيوانية في الوطن العربي","src":[85,86],"blocks":[{"t":"map","img":"assets/b-u3-livestock.jpg","cap":"خريطة (١) أولى دول الوطن العربي إنتاجًا للثروة الحيوانية"},{"t":"cards","items":[{"icon":"cow","h":"١- الأبقار والأغنام والماعز والخيول","body":"تُعد السودان من أكثر الدول العربية تربيةً لهذه الحيوانات؛ لوفرة المراعي الطبيعية بها."},{"icon":"camel","h":"٢- الإبل (الجِمال)","body":"تُعد الصومال أولى الدول العربية في تربية الإبل؛ نظرًا لطبيعة أراضيها الجافة."},{"icon":"buffalo","h":"٣- الجاموس","body":"تتوافر المياه والبيئة الرطبة للجاموس في وطننا العربي، وتحتل مصر المركز الأول عربيًّا في تربية الجاموس.","more":"وذلك بفضل البيئة الزراعية الخصبة على ضفاف نهر النيل التي تُعد مناسبة لتربية هذا الحيوان."}]},{"t":"ask","kind":"أفكر وأستنتج","q":["اذكر أسباب انتشار تربية الأغنام في السودان.","ما العلاقة بين الثروة الحيوانية والبيئة الفيضية في مصر؟"]},{"t":"chips","h":"أهمية الثروة الحيوانية: تُعد من أهم الموارد الاقتصادية في الوطن العربي؛ لأنها","items":["تُعد مصدرًا غذائيًّا غنيًّا بالبروتين الحيواني.","تُستخدم بعض الحيوانات في الزراعة والنقل.","توفر مواد خامًا لصناعات مثل الجلود والألبان واللحوم."]},{"t":"fact","kind":"قيم أتعلمها","text":"الاستثمار الحيواني يؤدي إلى إنتاج أفضل."}]},{"title":"مشكلات الثروة الحيوانية وجهود تنميتها","src":[86],"blocks":[{"t":"duo","a":{"h":"مشكلات الثروة الحيوانية في الوطن العربي","items":["نقص الأعلاف وارتفاع أسعارها.","قلة الرعاية البيطرية.","الإفراط في الرعي مما يضر بالمراعي الطبيعية.","التغيرات المناخية.","قلة المراعي الطبيعية."]},"b":{"h":"جهود الدول العربية لتنمية الثروة الحيوانية","items":["تصنيع الأعلاف بأسعار مناسبة.","تحسين الرعاية البيطرية.","استخدام الأساليب العلمية في الإنتاج الحيواني.","تنظيم المراعي وحمايتها.","تنفيذ مشروعات لمواجهة التغيرات المناخية وزيادة المساحات الخضراء."]}},{"t":"ask","kind":"أفكر وأستنتج","q":["اقترح فكرة تساعد في حماية المراعي من التدهور.","وضح العلاقة بين التغيرات المناخية وتدهور المراعي الطبيعية.","اقترح مشروعًا صغيرًا يسهم في تنمية الثروة الحيوانية."]}]},{"title":"الدواجن في الوطن العربي","src":[87],"blocks":[{"t":"intro","text":"تهتم الدول العربية بتربية الدواجن؛ لتعوض النقص في اللحوم الحمراء، وتُعد مصر والسعودية من أكثر الدول العربية إنتاجًا لها لوفرة الأعلاف والمَزارع الحديثة بهما."},{"t":"ask","kind":"ألاحظ وأفسر","q":["وضح سبب تصدُّر مصر والسعودية في إنتاج الدواجن."]}]},{"title":"الثروة السمكية في الوطن العربي","src":[87,88],"blocks":[{"t":"intro","text":"يتميز الوطن العربي بموارد مائية غنية تُوفر كميات كبيرة من الأسماك."},{"t":"map","img":"assets/b-u3-fish.jpg","cap":"خريطة (٢) مصايد الأسماك في الوطن العربي"},{"t":"duo","a":{"h":"المزارع السمكية ← مصر","items":["مصر أكبر دول الوطن العربي في إنتاج الأسماك من المزارع السمكية.","من أشهرها مزارع دلتا النيل وبركة غليون."]},"b":{"h":"المصايد السمكية ← المغرب","items":["(المحيطات – البحار – الأنهار – البحيرات).","المغرب أكبر دول الوطن العربي في إنتاج الأسماك من المصايد البحرية؛ بسبب طول سواحلها على المحيط الأطلنطي والبحر المتوسط."]}},{"t":"terms","items":[{"term":"المصايد السمكية","def":"مصادر طبيعية يتم الصيد منها مباشرة."},{"term":"المَزارع السمكية","def":"أماكن يتم فيها تربية الأسماك بطريقة حديثة ومنظَّمة."}]},{"t":"chips","h":"أهمية الثروة السمكية في الوطن العربي","items":["مصدر مهم للغذاء الغني بالبروتين.","سد النقص في اللحوم الحمراء.","توفير فرص عمل للشباب."]}]},{"title":"مشكلات الثروة السمكية وجهود تنميتها","src":[88],"blocks":[{"t":"duo","a":{"h":"مشكلات الثروة السمكية في الوطن العربي","items":["الصيد الجائر للأسماك.","تلوث المياه بسبب المخلفات والنفايات.","استخدام وسائل صيد بدائية.","التغير المناخي وارتفاع درجة حرارة المياه ونقص الأكسجين.","ترك الصيادين لحرفة الصيد."]},"b":{"h":"جهود الدول العربية لتنمية الثروة السمكية","items":["منع الصيد الجائر.","سن القوانين للحد من التلوث وتنظيم عملية الصيد.","توفير وسائل صيد حديثة وآمنة.","التوسع في مشروعات الاستزراع السمكي.","تحسين أحوال الصيادين."]}},{"t":"ask","kind":"أناقش وأجيب","q":["اقترح طريقة للحفاظ على نظافة المياه، واعرضها على معلمك.","وضح العلاقة بين الاستزراع السمكي وزيادة الإنتاج الغذائي."]}]},{"title":"تدريبات الدرس","src":[89,90,91],"ex":true,"blocks":[{"t":"read","h":"اقرأ وحلل: الثروة الحيوانية في الوطن العربي (نص إثرائي)","text":"تلعب الثروة الحيوانية دورًا مهمًّا في حياة سكان الوطن العربي، فهي مصدر رئيسي للحوم والألبان والجلود والصوف، كما تُستخدم بعض الحيوانات في أعمال الزراعة والنقل، خاصة في المناطق الريفية. ومن أهم الحيوانات التي يربيها الإنسان: الأغنام، والأبقار، والماعز، والإبل."},{"t":"ask","kind":"اقرأ وحلل","q":["ما أهمية الثروة الحيوانية في حياة سكان الوطن العربي؟","اذكر بعض الاستخدامات المفيدة للحيوانات في الريف."]},{"t":"read","h":"اقرأ واستنتج: الثروة السمكية في وطننا العربي (نص إثرائي)","text":"يمتلك الوطن العربي سواحل طويلة تُطِل على البحار والمحيطات، مما جعله غنيًّا بالثروة السمكية. وتُعد الأسماك مصدرًا مهمًّا للبروتين، كما أنها تُستخدم في صناعات مثل الزيوت والعلف. وتواجه الثروة السمكية بعض التحديات مثل التلوث والصيد الجائر؛ لذلك تعمل الدول العربية على حماية البحار وتنمية مشاريع الاستزراع السمكي."},{"t":"ask","kind":"اقرأ واستنتج","q":["ما سبب غنى الوطن العربي بالثروة السمكية؟","ما الفوائد الغذائية التي نحصل عليها من الأسماك؟","استنتج حلولًا للتحديات التي تواجه الثروة السمكية."]},{"t":"ask","kind":"اكتب (صواب) أو (خطأ)","q":["تعتمد الصناعات الجلدية على الأسماك.","الرعي الجائر يسهم في الحفاظ على المراعي.","إحدى فوائد الثروة الحيوانية توفير مواد خام للصناعة.","يتركز الجاموس في المناطق الجافة الصحراوية.","تعتمد الدول العربية على استيراد اللحوم رغم امتلاكها ثروة حيوانية كبيرة.","تعتمد الثروة الحيوانية على المراعي الطبيعية."]},{"t":"ask","kind":"اختر الإجابة الصحيحة مما بين القوسين","q":["أحد الحيوانات التي ترعى في البيئة الصحراوية …… (الخيل – الإبل – الجاموس – الأبقار)"]},{"t":"ask","kind":"أكمل العبارات التالية بكلمات مناسبة","q":["الدول العربية الكبرى في إنتاج الدواجن ……","تُعد الثروة الحيوانية مصدرًا لـ ……","تتمثل أهم تحديات الثروة السمكية في ……","إحدى وسائل حماية الثروة الحيوانية ……"]},{"t":"ask","kind":"بم تفسر…؟","q":["اهتمام الدول العربية بتربية الماشية.","أهمية الثروة السمكية.","انتشار تربية الإبل في المناطق الصحراوية."]},{"t":"ask","kind":"ما النتائج المترتبة على…؟","q":["التغيرات المناخية بالنسبة للثروة الحيوانية.","التوسع في مشروعات الاستزراع السمكي."]},{"t":"ask","kind":"دلل على صحة العبارات التالية","q":["تسهم الدواجن في تحقيق الأمن الغذائي للسكان.","وفرة المراعي الطبيعية تساعد في تربية الحيوانات."]},{"t":"ask","kind":"وضح العلاقة بين","q":["تدهور المراعي الطبيعية والتغير المناخي."]},{"t":"ask","kind":"ماذا يحدث إذا…؟","q":["ازداد التلوث في البحار العربية.","لم تهتم الدول العربية بتطوير الثروة السمكية."]},{"t":"ask","kind":"قارن بين كل من","q":["المزارع السمكية والمصايد السمكية من حيث أولى الدول العربية إنتاجًا.","أولى الدول العربية في تربية الإبل والجاموس والأبقار."]},{"t":"ask","kind":"هيا نستعد للدرس القادم","q":["هناك عديد من المعادن ومصادر الطاقة بالوطن العربي. ما أهمية هذه الموارد؟ وكيف ساعدت على تقدُّم الوطن العربي؟"]}]}],"blocks":36,"hasEx":true},{"id":"u3l3","unit":3,"n":3,"title":"المعادن ومصادر الطاقة في وطننا العربي","bookPages":[92,99],"icon":"gem","objectives":["أفسّر أهمية المعادن ومصادر الطاقة في حياتنا.","أقدِّم أمثلة للمعادن ومصادر الطاقة والدول المنتجة لها.","أقترح حلولًا للتحديات التي تواجه الوطن العربي واستغلال المعادن ومصادر الطاقة."],"panels":[{"title":"الثروة المعدنية في الوطن العربي","src":[92,93],"blocks":[{"t":"intro","text":"يمتلك وطننا العربي ثروات معدنية هائلة، ومصادر طاقة متنوعة، نستخدمها في حياتنا اليومية، وهي من أهم أسباب تقدُّم الدول وازدهارها."},{"t":"ask","kind":"أتأمل وأكتشف","q":["ما الموارد المعدنية التي نستخدمها في صناعة الأشياء من حولنا؟"]},{"t":"duo","a":{"h":"المعادن","items":["الحديد","النحاس","الذهب","المنجنيز"]},"b":{"h":"الصخور الاقتصادية","items":["الفوسفات","الكبريت"]}},{"t":"map","img":"assets/b-u3-minerals.jpg","cap":"خريطة (١) أولى الدول المنتجة للمعادن بالوطن العربي"}]},{"title":"أهم المعادن وأماكن وجودها وفوائدها","src":[93,94],"blocks":[{"t":"compare","head":["المعدن","أولى الدول إنتاجًا له","استخداماته"],"rows":[["١- الحديد","موريتانيا والجزائر ومصر.","يُستخدم في بناء الكباري وصناعة القطارات والسيارات."],["٢- النحاس","سلطنة عُمان والمغرب.","يُستخدم في صناعة الأسلاك الكهربائية والأجهزة الإلكترونية."],["٣- الذهب","السودان ومصر.","يُستخدم في صناعة الحُلي والعملات وبعض الأدوية."],["٤- المنجنيز","المغرب ومصر.","يُستخدم في صناعة الصلب ومواد الطلاء."],["٥- الفوسفات","المغرب ومصر والأردن.","يُستخدم في صناعة الأسمدة الزراعية والطوب الحراري."],["٦- الكبريت","العراق والجزائر.","يُستخدم في صناعة الأدوية والصناعات الكيميائية."]]},{"t":"note","text":"هكذا يا أصدقائي، تعرَّفنا خلال رحلتنا على كنوز وطننا العربي المدفونة في باطن الأرض، فهي ثروات عظيمة علينا المحافظة عليها واستغلالها بشكل يخدم التنمية ويحمي البيئة."},{"t":"fact","kind":"حقائق تاريخية","text":"أدركت الحضارات القديمة أهمية المعادن، فاستخرج المصريون القدماء الذهب من الصحراء الشرقية واستخدموه في أدوات الزينة، كما استخدمت حضارة بلاد الرافدين المعادن في صناعة أدوات الزراعة والطب والكتابة."},{"t":"ask","kind":"أفكر وأستنتج","q":["ما أهم استخدامات الحديد والنحاس؟"]},{"t":"ask","kind":"أقرأ وأحلل","q":["حدد اسم المعدن الأكثر أهمية للاقتصاد العربي.","فسِّر أهمية الفوسفات في الزراعة.","دلل على أن وطننا العربي غني بالمعادن.","وضح العلاقة بين المنجنيز وصناعة الصلب."]}]},{"title":"مصادر الطاقة غير المتجددة","src":[95,96],"blocks":[{"t":"intro","text":"يمتلك وطننا العربي أنواعًا متعددة من مصادر الطاقة، وهي نوعان: غير متجددة ومتجددة، وهي أساس التقدم والرفاهية في حياتنا."},{"t":"map","img":"assets/b-u3-energy.jpg","cap":"خريطة (٢) مصادر الطاقة غير المتجددة بالوطن العربي"},{"t":"cards","items":[{"icon":"oil","h":"١- البترول","body":"يُستخدم في تشغيل المصانع والسيارات والطائرات، ويدخل في صناعة البلاستيك.","more":"ومن أكثر دول الوطن العربي إنتاجًا له السعودية والعراق والكويت، وهو سبب رئيسي في قوة الاقتصاد لبعض دول وطننا العربي."},{"icon":"flame","h":"٢- الغاز الطبيعي","body":"يُستخدم في الطهي وتوليد الكهرباء وتشغيل المصانع.","more":"ومن أكثر دول الوطن العربي إنتاجًا له قطر والجزائر ومصر، وهو أقل مصادر الطاقة غير المتجددة تلويثًا للبيئة."},{"icon":"coal","h":"٣- الفحم","body":"يُستخدم في المصانع لصهر الحديد.","more":"ومن أكثر دول الوطن العربي إنتاجًا له المغرب ومصر، وهو أكثر مصادر الطاقة غير المتجددة تلويثًا للبيئة."}]},{"t":"ask","kind":"أفهم وأجيب","q":["فسِّر: يُعد البترول من أهم مصادر الدخل في بعض دول وطننا العربي.","أيهما أكثر ضررًا من حيث التأثير على البيئة (الفحم – الغاز الطبيعي)؟"]}]},{"title":"مصادر الطاقة المتجددة","src":[96],"blocks":[{"t":"cards","items":[{"icon":"sun","h":"١- الطاقة الشمسية","body":"تُستخدم في توليد الكهرباء وتسخين المياه وتشغيل الأجهزة.","more":"وتعتمد عليها عديد من الدول العربية، منها مصر والجزائر والسعودية."},{"icon":"wind","h":"٢- طاقة الرياح","body":"تساعد في توليد الكهرباء من خلال التوربينات (دوارة الرياح).","more":"وأكثر الدول إنتاجًا لها مصر والمغرب وتونس."},{"icon":"wave","h":"٣- الطاقة المائية","body":"تُستخدم في توليد الكهرباء بطريقة آمنة ونظيفة.","more":"وأكثر دول الوطن العربي اعتمادًا عليها مصر والسودان."}]},{"t":"fact","kind":"قيم أتعلمها","text":"سوء استخدام الإنسان لثروات الأرض قد يعرضها للنفاد."},{"t":"ask","kind":"أفكر وأستنتج","q":["ماذا يحدث إذا اعتمدت الدول العربية على الطاقة المتجددة بدلًا من غير المتجددة؟","اكتب فقرة عن أحد مصادر الطاقة المتجددة في الوطن العربي واعرضها في الإذاعة المدرسية."]}]},{"title":"تدريبات الدرس","src":[97,98,99],"ex":true,"blocks":[{"t":"read","h":"اقرأ وحلل: المعادن كنوز الأرض (نص إثرائي)","text":"المعادن هي ثروات طبيعية توجد في باطن الأرض، وتُعد من أهم الموارد التي اعتمدت عليها الحضارات منذ آلاف السنين، فهي مواد صلبة، تختلف في اللون والشكل والخواص، ولكل معدن استخدام معين في حياتنا.\nلا تقتصر أهمية المعادن على الصناعة فقط، بل تمتد إلى الزراعة والطب، مثل الفوسفات الذي يُستخدم في صناعة الأسمدة، والكبريت الذي يدخل في صناعة الأدوية.\nيُعد الوطن العربي من أغنى مناطق العالم بالمعادن، حيث تتوافر فيه كميات كبيرة من الذهب والحديد والفوسفات والنحاس والمنجنيز. وتُعد هذه الثروات من ركائز الاقتصاد العربي."},{"t":"ask","kind":"اقرأ وحلل","q":["لماذا يجب علينا استخدام المعادن بحكمة؟","ما العلاقة بين المعادن والتقدم الصناعي في الوطن العربي؟","الفوسفات معدن مهم في الزراعة، ويُستخدم في صناعة ……"]},{"t":"ask","kind":"اقرأ وتعلم","q":["اختر معدنًا من معادن الوطن العربي (الذهب – الحديد – الفوسفات – النحاس – الكبريت…)، ثم اكتب فقرة قصيرة على لسان هذا المعدن وكأنه «شخصية تتكلم» تعرِّف بنفسها وتشرح: من أنا؟ – أماكن وجودي. – كيف يستخدمني الناس؟ – لماذا أنا مهم في حياة الإنسان؟","اكتب رسالة توعية لاستخدام المعادن بشكل مستدام. (رسالة توعية للحفاظ على المعادن)."]},{"t":"ask","kind":"اكتب (صواب) أو (خطأ)","q":["يُستخدم النحاس في صناعة الأدوية.","الغاز الطبيعي أقل تلويثًا من البترول والفحم.","وطننا العربي فقير في مصادر الطاقة والمعادن.","الطاقة المائية تنتج من الأنهار والسدود دون تلويث البيئة.","تُعد المعادن من الموارد المتجددة التي لا تنفد مع الزمن."]},{"t":"ask","kind":"اختر الإجابة الصحيحة مما بين القوسين","q":["يُستخدم النحاس بشكل رئيسي في صناعة …… (الطوب – الحُلي – الأسلاك الكهربائية – الأدوية)","أكثر الدول العربية إنتاجًا للذهب هما …… (قطر واليمن – مصر والسودان – تونس وسوريا – العراق والكويت)","معدن يُستخدم في صناعة الصلب ومواد الطلاء …… (الفوسفات – المنجنيز – الكبريت – الذهب)","الطاقة التي تنتج من المياه تُسمى …… (الطاقة الشمسية – طاقة الرياح – الطاقة الكهرومائية – الطاقة النووية)","أكثر مصادر الطاقة تلويثًا للهواء هو …… (الغاز الطبيعي – الفحم – الطاقة الشمسية – طاقة الرياح)","أكبر دول وطننا العربي في إنتاج طاقة الرياح …… (المغرب – الجزائر – مصر – السعودية)","مصدر الطاقة الذي لا ينتهي ويمكن استخدامه في جميع الدول العربية …… (الفحم – الشمس – الغاز الطبيعي – البترول)"]},{"t":"ask","kind":"بم تفسر…؟","q":["تُعد الطاقة الشمسية مصدرًا صديقًا للبيئة.","غنى الوطن العربي بالمعادن.","ضرورة الحفاظ على المعادن ومصادر الطاقة."]},{"t":"ask","kind":"دلل على صحة العبارات التالية","q":["تُستخدم المعادن في مجالات متعددة في حياتنا.","أهمية البترول في بعض الدول العربية."]},{"t":"ask","kind":"ما العلاقة بين كل من…؟","q":["الفحم والبيئة.","الحديد والصناعة الحديثة.","الطاقة والتنمية الاقتصادية."]},{"t":"ask","kind":"ما الفرق بين…؟","q":["الطاقة الشمسية والطاقة الكهرومائية."]},{"t":"ask","kind":"ما النتائج المترتبة على…؟","q":["الاعتماد على مصادر الطاقة غير المتجددة؟"]},{"t":"ask","kind":"هيا نستعد للدرس القادم","q":["يتميز وطننا العربي بوفرة مقومات السياحة. ما أنواع السياحة التي يمكن أن توجد في وطننا؟ وأي نوع منها تفضِّله؟"]}]}],"blocks":27,"hasEx":true},{"id":"u3l4","unit":3,"n":4,"title":"النشاط السياحي في وطننا العربي","bookPages":[100,105],"icon":"pyramid","objectives":["أوضح المقومات التي تساعد على جذب السياح إلى وطننا العربي.","أميِّز بين أنواع السياحة في وطننا العربي.","أفسِّر أهمية النشاط السياحي لوطننا العربي.","أقدِّر جهود الحكومات العربية في النشاط السياحي."],"panels":[{"title":"مقومات السياحة في الوطن العربي","src":[100],"blocks":[{"t":"intro","text":"يُعد الوطن العربي من أهم المناطق التي تجذب السائحين من كل مكان في العالم؛ لأنه يتميز بطبيعة خلابة وتاريخ قديم، وتُعد السياحة مصدرًا مهمًّا للدخل، وفرصة للتعرُّف على حضاراته الرائعة والمميزة."},{"t":"ask","kind":"أتأمل وأكتشف","q":["هل فكرت يومًا لماذا يُفضِّل السياح زيارة وطننا العربي دون غيره؟"]},{"t":"duo","a":{"h":"المقومات الطبيعية","items":["الموقع المميز","المناخ المعتدل","التنوع الطبيعي"]},"b":{"h":"المقومات البشرية","items":["تنوع الآثار","حسن الضيافة","الفنادق والقرى السياحية","النقل والمواصلات","توافر الأمن والأمان"]}},{"t":"ask","kind":"أتعاون وأشارك","q":["ما النتائج المترتبة على تنوع المقومات السياحية (الطبيعية والبشرية) في الوطن العربي؟"]}]},{"title":"أنواع السياحة في الوطن العربي","src":[101,102],"blocks":[{"t":"cards","items":[{"icon":"kaaba","h":"١- السياحة الدينية","body":"فيها يزور الناس الأماكن المقدَّسة.","more":"مثل: المسجد الحرام في السعودية، والمسجد الأقصى وكنيسة المهد في فلسطين."},{"icon":"pyramid","h":"٢- السياحة الثقافية","body":"مثل زيارة المتاحف والآثار.","more":"منها: الأهرامات ومدينة الأقصر في مصر، وبابل في العراق، والقيروان في تونس."},{"icon":"drop","h":"٣- السياحة العلاجية","body":"يزور الناس أماكن تحتوي على مياه معدنية.","more":"مثل: عيون موسى والعيون الكبريتية في مصر، وعين ماعين في الأردن."},{"icon":"wave","h":"٤- السياحة الترفيهية","body":"للاستمتاع بالشواطئ والطبيعة.","more":"مثل: شرم الشيخ والغردقة في مصر، وجزر القُمر وسلطنة عُمان."},{"icon":"market","h":"٥- سياحة التسوق","body":"يزور الناس أماكن التسوق لشراء الهدايا.","more":"مثل: الأسواق الشعبية في المغرب، وأماكن التسوق الحديثة في الإمارات والكويت والبحرين."},{"icon":"tree","h":"٦- السياحة البيئية","body":"زيارة المحميات الطبيعية.","more":"مثل: محمية أرز الشوف في لبنان، ومحمية علبة في مصر، ومحمية ضانا في الأردن."},{"icon":"city","h":"٧- سياحة المؤتمرات والمعارض","body":"حضور المؤتمرات العلمية والثقافية.","more":"مثل مصر والسعودية والإمارات والكويت والبحرين."},{"icon":"ball","h":"٨- السياحة الرياضية","body":"حضور البطولات والمباريات مثل كأس العالم في قطر.","more":"أو المشاركة في أنشطة رياضية مثل الغوص وركوب الجِمال."}]},{"t":"ask","kind":"أحدد وأصنف","q":["صنف الأماكن والأحداث التالية وفق نوع السياحة في جدول من تصميمك، واعرضه على معلمك: (مكة – الأهرامات – البحر الميت – شرم الشيخ – محمية أرز الشوف – مول الإمارات – كأس آسيا – مؤتمر التعليم العربي)."]}]},{"title":"أهمية السياحة في الوطن العربي","src":[102],"blocks":[{"t":"chips","h":"أهمية السياحة","items":["مصدر مهم للدخل القومي للدول العربية.","تُساعد على تبادل الثقافات والتواصل بين الشعوب.","توفر فرص عمل للشباب في الفنادق والمطاعم ووسائل النقل.","تشجع على تطوير المدن والبنية التحتية."]}]},{"title":"تنمية السياحة وجهود الحكومات العربية","src":[103],"blocks":[{"t":"intro","text":"تبذل الدول العربية جهودًا كبيرة لتنمية السياحة؛ لأنها مصدر مهم للدخل وفرص العمل."},{"t":"chips","h":"وقد قامت الحكومات العربية بعدة خطوات، منها","items":["الاهتمام بتوفير الأمن والأمان.","تدريب وتأهيل العاملين في السياحة.","تنظيم مهرجانات وفعاليات لجذب السياح.","تطوير الأماكن السياحية القديمة وتجديدها.","إنشاء مطارات وفنادق حديثة لاستقبال السياح."]},{"t":"note","text":"وتُسهم هذه الجهود في جذب مزيد من السياح، ومعرفة العالم بجمال وروعة الحضارة في وطننا العربي."},{"t":"fact","kind":"قيم أتعلمها","text":"حماية الآثار والحفاظ على الأماكن السياحية واجب علينا جميعًا."},{"t":"fact","kind":"مصر بين المستقبل والحاضر","text":"تبذل مصر جهودًا كبيرة لتنشيط السياحة مثل: إنشاء المتحف المصري الكبير، وتطوير منطقة الأهرامات، وبناء مدن سياحية جديدة مثل العلمين الجديدة، وتنظيم احتفالات عالمية مثل موكب المومياوات، إلى جانب توفير الأمن وتحسين البنية التحتية وبناء الفنادق. كل هذا لجذب السياح وتعريفهم بحضارة مصر."},{"t":"ask","kind":"أتعلم وأطبق","q":["تخيل نفسك وزيرًا للسياحة واكتب مقترحًا لتنمية السياحة في الوطن العربي.","وضح العلاقة بين السياحة وفرص العمل والدخل القومي."]},{"t":"chips","h":"نماذج من الدول العربية للتنمية السياحية: تسعى الدول العربية إلى تنمية السياحة؛ وذلك بهدف جذب السياح وتنشيط الاقتصاد المحلي، ويتم ذلك من خلال عدة مشروعات","items":["تهتم دولة الإمارات العربية المتحدة بالسياحة من خلال عدة مشاريع مثل برج خليفة وجزيرة النخلة.","تنظم السعودية فعاليات مثل موسم الرياض لتشجيع السياحة الترفيهية.","تهتم المغرب وتونس بالمدن القديمة والمواقع التراثية لتنشيط السياحة الثقافية."]},{"t":"ask","kind":"أناقش وأقترح","q":["ما الهدف من تطوير الدول العربية للمناطق السياحية؟","اذكر مثالين لجهود الدول العربية في تنشيط السياحة."]}]},{"title":"تدريبات الدرس","src":[104,105],"ex":true,"blocks":[{"t":"read","h":"اقرأ وحلل: دور السياحة في تنمية القيم والاقتصاد (نص إثرائي)","text":"السياحة تُعلمنا الكثير من القيم الجميلة، مثل احترام الآخرين، والاعتزاز بتاريخ بلادنا والمحافظة على النظافة والآثار، كما تُعزز التعاون بين الدول العربية، وتوفر فرص عمل، وتنشط مجالات مثل النقل والتجارة والفندقة، كما تسهم في تحسين البنية التحتية وتجميل المدن؛ ولهذا تهتم الحكومات بتنميتها وتطويرها."},{"t":"ask","kind":"اقرأ وحلل","q":["ما القيم التي نكتسبها من الاهتمام بالسياحة؟","دلل على أن السياحة وسيلة لنشر الوعي الثقافي بين الشعوب.","ما رأيك: هل السياحة وسيلة للسلام والتواصل بين الشعوب؟ لماذا؟"]},{"t":"ask","kind":"فكر وخطط","q":["قم بالتخطيط لرحلة إلى إحدى الدول العربية تتضمن: (اسم الدولة – نوع السياحة – أبرز الأماكن التي سيزورها السائح – وسيلة النقل – ملاحظات خاصة لجذب السائحين)."]},{"t":"ask","kind":"اكتب (صواب) أو (خطأ)","q":["تُعد السياحة مصدرًا مهمًّا للدخل القومي في عديد من الدول العربية.","حضور مؤتمر المناخ من أنواع السياحة البيئية في الوطن العربي.","تشتهر مصر والإمارات والسعودية بأنشطة سياحية متنوعة.","تُعد السياحة في الوطن العربي محدودة بسبب عدم وجود معالم طبيعية.","إقامة المهرجانات والفعاليات تساعد على جذب السياح."]},{"t":"ask","kind":"أكمل العبارات التالية بكلمات مناسبة","q":["من المقومات الطبيعية للسياحة …… و ……","الدول المشهورة بالسياحة الدينية …… و ……","تهتم الحكومات العربية بتنمية السياحة من خلال …… و ……","من آثار السياحة على الاقتصاد …… و ……","من جهود مصر الحديثة في السياحة …… و ……"]},{"t":"ask","kind":"بم تفسر…؟","q":["أهمية السياحة في وطننا العربي.","إقبال السياح على زيارة دول مثل مصر ولبنان والمغرب."]},{"t":"ask","kind":"ما النتائج المترتبة على…؟","q":["تنمية السياحة في الوطن العربي؟"]},{"t":"ask","kind":"دلل على صحة العبارات الآتية","q":["السياحة تؤثر على الاقتصاد العربي.","هناك جهود حقيقية من الدول العربية لتنمية السياحة."]},{"t":"ask","kind":"أجب عما يلي","q":["ما العلاقة بين الأمن والاستقرار وحركة السياحة؟","ما أنواع السياحة في الوطن العربي؟"]}]}],"blocks":24,"hasEx":true}],"pageOffset":1};
